export const BOOK_QS = [{"chapter":1,"num":1,"text":"Your developers want to run fully provisioned EC2 instances to support their application code deployments but prefer not to have to worry about manually configuring and launching the necessary infrastructure. Which of the following should they use?","options":{"A":"AWS Lambda","B":"AWS Elastic Beanstalk","C":"Amazon EC2 Auto Scaling","D":"Amazon Route 53"},"answer":["B"],"explanation":"Elastic Beanstalk handles provisioning, load balancing, auto-scaling, and application health monitoring while keeping the underlying EC2 instances fully accessible.","multi":false},{"chapter":1,"num":2,"text":"Some of your application's end users are complaining of delays when accessing your resources from remote geographic locations. Which of these services would be the most likely to help reduce the delays?","options":{"A":"Amazon CloudFront","B":"Amazon Route 53","C":"Elastic Load Balancing","D":"Amazon Glacier"},"answer":["A"],"explanation":"Amazon CloudFront is a content delivery network (CDN) that caches content at edge locations worldwide to reduce latency for global users.","multi":false},{"chapter":1,"num":3,"text":"Which of the following is the best use- case scenario for Elastic Block Store?","options":{"A":"You need a cheap and reliable place to store files your application can access.","B":"You need a safe place to store backup archives from your local servers.","C":"You need a source for on- demand compute cycles to meet fluctuating demand for your application.","D":"You need persistent storage for the filesystem run by your EC2 instance."},"answer":["D"],"explanation":"Amazon EBS provides persistent, high-performance block storage volumes designed for use with a single Amazon EC2 instance.","multi":false},{"chapter":1,"num":4,"text":"You need to integrate your company's local user access controls with some of your AWS resources. Which of the following can help you control the way your local users access your AWS services and administration console? (Choose two.)","options":{"A":"AWS Identity and Access Management (IAM)","B":"Key Management Service (KMS)","C":"AWS Directory Service","D":"Simple WorkFlow (SWF)","E":"Amazon Cognito"},"answer":["A","C"],"explanation":"AWS Directory Service connects AWS resources with an on-premises Active Directory, while IAM handles identity delegation and permissions management.","multi":true},{"chapter":1,"num":5,"text":"The data consumed by the application you're planning will require more speed and flexibility than you can get from a closely defined relational database structure. Which AWS database service should you choose?","options":{"A":"Relational Database Service (RDS)","B":"Amazon Aurora","C":"Amazon DynamoDB","D":"Key Management Service (KMS)"},"answer":["C"],"explanation":"Amazon DynamoDB is a fully managed NoSQL database service that provides fast, flexible, non-relational key-value and document storage.","multi":false},{"chapter":1,"num":6,"text":"You've launched an EC2 application server instance in the AWS Ireland region and you need to access it from the web. Which of the following is the correct endpoint address that you should use?","options":{"A":"compute.eu-central-1.amazonaws.com","B":"ec2.eu-central- 1.amazonaws.com","C":"elasticcomputecloud.eu-west-2.amazonaws.com","D":"ec2.eu- west-1.amazonaws.com"},"answer":["D"],"explanation":"The standard AWS service endpoint format for EC2 in the Ireland region is ec2.eu-west-1.amazonaws.com.","multi":false},{"chapter":1,"num":7,"text":"When working to set up your first AWS deployment, you keep coming across the term avail- availability zone. What exactly is an availability zone?","options":{"A":"An isolated physical datacenter within an AWS region","B":"A region containing multiple isolated datacenters","C":"A single network subnet used by resources within a single region","D":"A single isolated server room within a datacenter"},"answer":["A"],"explanation":"An Availability Zone (AZ) consists of one or more discrete, physically isolated datacenters with redundant power, networking, and connectivity within an AWS Region.","multi":false},{"chapter":1,"num":8,"text":"As you plan your multi- tiered, multi- instance AWS application, you need a way to effectively organize your instances and configure their network connectivity and access control. Which tool will let you do that?","options":{"A":"Load Balancing","B":"Amazon Virtual Private Cloud (VPC)","C":"Amazon CloudFront","D":"AWS endpoints"},"answer":["B"],"explanation":"Amazon VPC lets you provision a logically isolated section of the AWS cloud to launch and organize resources in your own custom network.","multi":false},{"chapter":1,"num":9,"text":"You want to be sure that the application you're building using EC2 and S3 resources will be reliable enough to meet the regulatory standards required within your industry. What should you check?","options":{"A":"Historical uptime log records","B":"The AWS Program Compliance Tool","C":"The AWS service level agreement (SLA)","D":"The AWS Compliance Programs documentation page","E":"The AWS Shared Responsibility Model"},"answer":["D"],"explanation":"The AWS Compliance Programs documentation page provides detailed information regarding various industry-specific certifications and compliance standards met by AWS.","multi":false},{"chapter":1,"num":10,"text":"Your organization's operations team members need a way to access and administer your AWS infrastructure via your local command line or shell scripts. Which of the following tools will let them do that?","options":{"A":"AWS Config","B":"AWS CLI","C":"AWS SDK","D":"The AWS Console"},"answer":["B"],"explanation":"The AWS Command Line Interface (CLI) is a unified tool that enables local shell and command-line execution to manage AWS services.","multi":false},{"chapter":1,"num":11,"text":"While building a large AWS- based application, your company has been facing configuration problems they can't solve on their own. As a result, they need direct access to AWS support for both development and IT team leaders. Which support plan should you purchase?","options":{"A":"Business","B":"Developer","C":"Basic","D":"Enterprise"},"answer":["A"],"explanation":"The Business support plan offers 24/7 access to cloud support engineers for multiple project leaders and team members facing production issues.","multi":false},{"chapter":1,"num":12,"text":"You've got a complex, multi- tiered application running on local servers that you want to migrate to the cloud. Which of these tools will provide you with the specific tools you'll need to move the application with the least risk and the least disruption?","options":{"A":"AWS Application Migration Service","B":"AWS Migration Hub","C":"AWS Application Discovery Service","D":"AWS Lift and Shift"},"answer":["A"],"explanation":"AWS Application Migration Service (AWS MGN) minimizes downtime and risks by automatically converting physical, virtual, or cloud servers to run natively on AWS.","multi":false},{"chapter":2,"num":1,"text":"You need to deploy multiple EC2 Linux instances that will provide your company with virtual private networks (VPNs) using software called OpenVPN. Which of the following will be the most efficient solutions? (Choose two.)","options":{"A":"Select a regular Linux AMI and bootstrap it using user data that will install and configure the OpenVPN package on the instance and use it for your VPN instances.","B":"Search the community AMIs for an official AMI provided and supported by the OpenVPN company.","C":"Search the AWS Marketplace to see whether there's an official AMI provided and supported by the OpenVPN company.","D":"Select a regular Linux AMI and SSH to manually install and configure the OpenVPN package.","E":"Create a site- to- site VPN connection from the wizard in the AWS VPC dashboard."},"answer":["A","C"],"explanation":"Using an official Marketplace AMI is the most immediate turnkey option, while a user data script ensures a reliable, automated, and repeatable configuration pipeline.","multi":true},{"chapter":2,"num":2,"text":"As part of your company's long-term cloud migration strategy, you have a VMware virtual machine in your local infrastructure that you'd like to copy to your AWS account and run as an EC2 instance. Which of the following will be necessary steps? (Choose two.)","options":{"A":"Import the virtual machine to your AWS region using a secure SSH tunnel.","B":"Import the virtual machine using VM Import/Export.","C":"Select the imported VM from among your private AMIs and launch an instance.","D":"Select the imported VM from the AWS Marketplace AMIs and launch an instance.","E":"Use the AWS CLI to securely copy your virtual machine image to an S3 bucket within the AWS region you'll be using."},"answer":["B","E"],"explanation":"VM Import/Export requires uploading the virtual machine image file into an Amazon S3 bucket first, before invoking the API to convert it into an AMI.","multi":true},{"chapter":2,"num":3,"text":"Your AWS CLI command to launch an AMI as an EC2 instance has failed, giving you an error message that includes InvalidAMIID.NotFound. What of the following is the most likely cause?","options":{"A":"You haven't properly configured the ~/.aws/config file.","B":"The AMI is being updated and is temporarily unavailable.","C":"Your key pair file has been given the wrong (overly permissive) permissions.","D":"The AMI you specified exists in a different region than the one you've currently specified."},"answer":["D"],"explanation":"AMIs are strictly region-specific; attempting to launch an AMI ID outside its home region triggers an InvalidAMIID.NotFound error.","multi":false},{"chapter":2,"num":4,"text":"The sensitivity of the data your company works with means that the instances you run must be secured through complete physical isolation. What should you specify as you configure a new instance?","options":{"A":"Dedicated Host tenancy","B":"Shared tenancy","C":"Dedicated Instance tenancy","D":"Isolated tenancy"},"answer":["A"],"explanation":"Dedicated Hosts allocate a fully isolated physical server for your absolute exclusive use, granting full visibility and control over instance placement.","multi":false},{"chapter":2,"num":5,"text":"Normally, two instances running m5.large instance types can handle the traffic accessing your online e-commerce site, but you know that you will face short, unpredictable periods of high demand. Which of the following choices should you implement? (Choose two.)","options":{"A":"Configure autoscaling.","B":"Configure load balancing.","C":"Purchase two m5.large instances on the spot market and as many on- demand instances as necessary.","D":"Shut down your m5.large instances and purchase instances using a more robust instance type to replace them.","E":"Purchase two m5.large reserve instances and as many on- demand instances as necessary."},"answer":["A","B"],"explanation":"An Elastic Load Balancer combined with an Auto Scaling group dynamically adjusts instance counts to gracefully adapt to sudden, variable performance demand.","multi":true},{"chapter":2,"num":6,"text":"Which of the following use cases would be most cost effective if run using spot market instances?","options":{"A":"Your e-commerce website is built using a publicly available AMI.","B":"You provide high- end video rendering services using a fault- tolerant process that can easily manage a job that was unexpectedly interrupted.","C":"You're running a backend database that must be reliably updated to keep track of critical transactions.","D":"Your deployment runs as a static website on S3."},"answer":["B"],"explanation":"Spot instances offer severe cost discounts but can be reclaimed by AWS with a two-minute warning, making them perfect for stateless, stateless, fault-tolerant rendering jobs.","multi":false},{"chapter":2,"num":7,"text":"In the course of a routine infrastructure audit, your organization discovers that some of your running EC2 instances are not configured properly and must be updated. Which of the following configuration details cannot be changed on an existing EC2 instance?","options":{"A":"AMI","B":"Instance type","C":"Security group","D":"Public IP address"},"answer":["A"],"explanation":"The base Amazon Machine Image (AMI) determines the root filesystem configuration at boot time and cannot be modified on a running instance.","multi":false},{"chapter":2,"num":8,"text":"For an account with multiple resources running as part of multiple projects, which of the following key/value combination examples would make for the most effective identification convention for resource tags?","options":{"A":"servers:server1","B":"project1:server1","C":"EC2:project1:server1","D":"server1:project1"},"answer":["B"],"explanation":"Structuring key-value tags as 'Project: Name' allows clean categorizations, programmatic sorting, and efficient financial cost-allocation tracking.","multi":false},{"chapter":2,"num":9,"text":"Which of the following EBS options will you need to keep your data- hungry application that requires up to 20,000 IOPS happy?","options":{"A":"Cold HDD","B":"General-purpose SSD","C":"Throughput- optimized HDD","D":"Provisioned- IOPS SSD"},"answer":["D"],"explanation":"Provisioned IOPS SSD volumes (io1/io2) are engineered to support intensive, high-throughput database workloads requiring explicit performance allocations up to tens of thousands of IOPS.","multi":false},{"chapter":2,"num":10,"text":"Your organization needs to introduce Auto Scaling to its infrastructure and needs to generate a \"golden image\" AMI from an existing EBS volume. This image will need to be shared among multiple AWS accounts belonging to your organization. Which of the following steps will get you there? (Choose three.)","options":{"A":"Create an image from a detached EBS volume, use it to create a snapshot, select your new AMI from your private collection, and use it for your launch configuration.","B":"Create a snapshot of the EBS root volume you need, use it to create an image, select your new AMI from your private collection, and use it for your launch configuration.","C":"Create an image from the EBS volume attached to the instance, select your new AMI from your private collection, and use it for your launch configuration.","D":"Search the AWS Marketplace for the appropriate image and use it for your launch configuration.","E":"Import the snapshot of an EBS root volume from a different AWS account, use it to create an image, select your new AMI from your private collection, and use it for your launch configuration."},"answer":["B","C","E"],"explanation":"An AMI can be registered directly from a live instance, built from an existing root volume snapshot, or derived from a cross-account shared snapshot.","multi":true},{"chapter":2,"num":11,"text":"Which of the following are benefits of instance store volumes? (Choose two.)","options":{"A":"Instance volumes are physically attached to the server that's hosting your instance, allowing faster data access.","B":"Instance volumes can be used to store data even after the instance is shut down.","C":"The use of instance volumes does not incur costs (beyond those for the instance itself).","D":"You can set termination protection so that an instance volume can't be accidentally shut down.","E":"Instance volumes are commonly used as a base for the creation of AMIs."},"answer":["A","C"],"explanation":"Instance stores are ephemeral block devices physically attached to the host hardware for ultra-low latency and are built directly into the base instance cost.","multi":true},{"chapter":2,"num":12,"text":"According to default behavior (and AWS recommendations), which of the following IP addresses could be assigned as the private IP for an EC2 instance? (Choose two.)","options":{"A":"54.61.211.98","B":"23.176.92.3","C":"172.17.23.43","D":"10.0.32.176","E":"192.140.2.118"},"answer":["C","D"],"explanation":"AWS VPC private subnets are allocated from RFC 1918 private address ranges, which include 10.0.0.0/8 and 172.16.0.0/12.","multi":true},{"chapter":2,"num":13,"text":"You need to restrict access to your EC2 instance- based application to only certain clients and only certain targets. Which three attributes of an incoming data packet are used by a security group to determine whether it should be allowed through? (Choose three.)","options":{"A":"Network port","B":"Source address","C":"Datagram header size","D":"Network protocol","E":"Destination address"},"answer":["A","B","D"],"explanation":"Security group inbound rules filter traffic exclusively based on protocol, port range, and source address block (CIDR/Security Group).","multi":true},{"chapter":2,"num":14,"text":"How are IAM roles commonly used to ensure secure resource access in relation to EC2 instances?","options":{"A":"A role can assign processes running on the EC2 instance itself permission to access other AWS resources.","B":"A user can be given permission to authenticate as a role and access all associated resources.","C":"A role can be associated with individual instance- based processes (Linux instances only), giving them permission to access other AWS resources.","D":"A role can give users and resources permission to access the EC2 instance."},"answer":["A"],"explanation":"Attaching an IAM role via an EC2 instance profile securely handles automated AWS API credential rotation for applications running on the instance.","multi":false},{"chapter":2,"num":15,"text":"You have an instance running within a private subnet that needs external network access to receive software updates and patches. Which of the following can securely provide that access from a public subnet within the same VPC? (Choose two.)","options":{"A":"Internet gateway","B":"NAT instance","C":"Virtual private gateway","D":"NAT gateway","E":"VPN"},"answer":["B","D"],"explanation":"NAT Gateways and legacy NAT instances allow resources within private subnets to securely initiate outbound IPv4 connections to the internet while blocking inbound traffic.","multi":true},{"chapter":2,"num":16,"text":"What do you have to do to securely authenticate to the GUI console of a Windows EC2 session?","options":{"A":"Use the private key of your key pair to initiate an SSH tunnel session.","B":"Use the public key of your key pair to initiate an SSH tunnel session.","C":"Use the public key of your key pair to retrieve the password you'll use to log in.","D":"Use the private key of your key pair to retrieve the password you'll use to log in."},"answer":["D"],"explanation":"AWS encrypts the Windows administrator password during setup; the administrator must supply the matching local private key (.pem file) to decrypt it.","multi":false},{"chapter":2,"num":17,"text":"Your application deployment includes multiple EC2 instances that need low- latency connections to each other. Which of the following AWS tools will allow you to locate EC2 instances closer to each other to reduce network latency?","options":{"A":"Load balancing","B":"Placement groups","C":"AWS Systems Manager","D":"AWS Fargate"},"answer":["B"],"explanation":"A cluster placement group packs instances close together inside a single Availability Zone to unlock ultra-low-latency network performance.","multi":false},{"chapter":2,"num":18,"text":"To save configuration time and money, you want your application to run only when network events trigger it but shut down immediately after. Which of the following will do that for you?","options":{"A":"AWS Lambda","B":"AWS Elastic Beanstalk","C":"Amazon Elastic Container Service (ECS)","D":"Auto Scaling"},"answer":["A"],"explanation":"AWS Lambda is a serverless, event-driven compute platform that executes code exclusively when triggered and incurs no costs when idle.","multi":false},{"chapter":2,"num":19,"text":"Which of the following will allow you to quickly copy a virtual machine image from your local infrastructure to your AWS VPC?","options":{"A":"AWS Simple Storage Service (S3)","B":"AWS Snowball","C":"VM Import/Export","D":"AWS Direct Connect"},"answer":["C"],"explanation":"VM Import/Export enables seamless migration of local VMware or Hyper-V virtual machine disk images directly into reusable Amazon EC2 AMIs.","multi":false},{"chapter":2,"num":20,"text":"You've configured an EC2 Auto Scaling group to use a launch configuration to provision and install an application on several instances. You now need to reconfigure Auto Scaling to install an additional application on new instances. Which of the following should you do?","options":{"A":"Modify the launch configuration.","B":"Create a launch template and configure the Auto Scaling group to use it.","C":"Modify the launch template.","D":"Modify the CloudFormation template."},"answer":["B"],"explanation":"Launch configurations are immutable and cannot be updated once created; migrating to a Launch Template allows versioning and easy structural modification.","multi":false},{"chapter":2,"num":21,"text":"You create an Auto Scaling group with a minimum group size of 3, a maximum group size of 10, and a desired capacity of 5. You then manually terminate two instances in the group. Which of the following will Auto Scaling do?","options":{"A":"Create two new instances.","B":"Reduce the desired capacity to 3.","C":"Nothing.","D":"Increment the minimum group size to 5."},"answer":["A"],"explanation":"Auto Scaling continuously compares running instance counts against the desired capacity (5) and provisions replacement nodes to correct deficits.","multi":false},{"chapter":2,"num":22,"text":"You're running an application that receives a spike in traffic on the first day of every month. You want to configure Auto Scaling to add more instances before the spike begins and then add additional instances in proportion to the CPU utilization of each instance. Which of the following should you implement? (Choose all that apply.)","options":{"A":"Target tracking policies","B":"Scheduled actions","C":"Step scaling policies","D":"Simple scaling policies","E":"Load balancing"},"answer":["A","B"],"explanation":"Scheduled actions proactively spin up baseline nodes prior to known structural load events, while target tracking scales dynamically to hold target metric bounds.","multi":true},{"chapter":2,"num":23,"text":"As part of your new data backup protocols, you need to manually take EBS snapshots of several hundred volumes. Which type of Systems Manager document enables you to do this?","options":{"A":"Command","B":"Automation","C":"Policy","D":"Manual"},"answer":["B"],"explanation":"Systems Manager Automation documents facilitate complex multi-step AWS infrastructure orchestrations like taking massive bulk snapshots across resources.","multi":false},{"chapter":2,"num":24,"text":"You want to launch and manage a complex microservices container workload in AWS but you want to avoid as many configuration headaches as possible, You figure you'll be fine with whatever defaults you're offered. Which of these platforms is your best choice?","options":{"A":"Amazon Elastic Kubernetes Service","B":"AWS Fargate","C":"Amazon EKS Distro","D":"Amazon Elastic Container Service"},"answer":["B"],"explanation":"AWS Fargate acts as a completely serverless container compute deployment model that strips away host-level management complexities entirely.","multi":false},{"chapter":3,"num":1,"text":"Your organization runs Linux- based EC2 instances that all require low- latency read/write access to a single set of files. Which of the following AWS services are your best choices? (Choose two.)","options":{"A":"AWS Storage Gateway","B":"AWS S3","C":"Amazon Elastic File System","D":"AWS Elastic Block Store"},"answer":["C","D"],"explanation":"Amazon EFS natively provides standard shared POSIX file access to thousands of concurrent instances, while multi-attach EBS blocks suit single-AZ clusters.","multi":true},{"chapter":3,"num":2,"text":"Your organization expects to be storing and processing large volumes of data in many small increments. When considering S3 usability, you'll need to know whether you'll face any practical limitations in the use of AWS account resources. Which of the following will normally be available only in limited amounts?","options":{"A":"PUT requests/month against an S3 bucket","B":"The volume of data space available per S3 bucket","C":"Account- wide S3 storage space","D":"The number of S3 buckets within a single account"},"answer":["D"],"explanation":"S3 permits limitless object data growth and request volumes but sets a soft structural limit of 100 buckets per account by default.","multi":false},{"chapter":3,"num":3,"text":"You have a publicly available file called filename stored in an S3 bucket named bucketname. Which of the following addresses will successfully retrieve the file using a web browser?","options":{"A":"s3.amazonaws.com/bucketname/filename","B":"filename/bucketname.s3.amazonaws.com","C":"s3://bucketname/filename","D":"s3://filename/bucketname"},"answer":["A"],"explanation":"The valid path-style web URL format for retrieving an object over standard HTTP/HTTPS protocols is s3.amazonaws.com/bucketname/filename.","multi":false},{"chapter":3,"num":4,"text":"If you want the files stored in an S3 bucket to be accessible using a familiar directory hierarchy system, you'll need to specify prefixes and delimiters. What are prefixes and delimiters?","options":{"A":"A prefix is the name common to the objects you want to group, and a delimiter is the bar character (|).","B":"A prefix is the DNS name that precedes the amazonaws.com domain, and a delimiter is the name you want to give your file directory.","C":"A prefix is the name common to the objects you want to group, and a delimiter is a forward slash character (/).","D":"A prefix is the name common to the file type you want to identify, and a delimiter is a forward slash character (/)."},"answer":["C"],"explanation":"S3 is a flat key-value object store; structural directories are simulated using folder path string prefixes separated by a forward slash (/) delimiter.","multi":false},{"chapter":3,"num":5,"text":"Your web application relies on data objects stored in AWS S3 buckets. Compliance with industry regulations requires that those objects be encrypted and that related events be closely tracked. Which combination of tools should you use? (Choose two.)","options":{"A":"Server- side encryption","B":"Amazon S3- Managed Keys","C":"AWS KMS- Managed Keys","D":"Client-side encryption","E":"AWS End-to- End managed keys"},"answer":["A","C"],"explanation":"Server-side encryption combined with AWS KMS provides managed encryption keys alongside robust AWS CloudTrail tracking for compliance logging.","multi":true},{"chapter":3,"num":6,"text":"You are engaged in a deep audit of the use of your AWS resources and you need to better understand the structure and content of your S3 server access logs. Which of the following operational details are likely to be included in S3 server access logs? (Choose three.)","options":{"A":"Source bucket name","B":"Action requested","C":"Current bucket size","D":"API bucket creation calls","E":"Response status"},"answer":["A","B","E"],"explanation":"S3 server access logs list execution actions, source bucket paths, time stamps, request IDs, and HTTP response status codes.","multi":true},{"chapter":3,"num":7,"text":"You're assessing the level of durability you'll need to sufficiently ensure the long-term viability of a new web application you're planning. Which of the following risks are covered by S3's data durability guarantees? (Choose two.)","options":{"A":"User misconfiguration","B":"Account security breach","C":"Infrastructure failure","D":"Temporary service outages","E":"Datacenter security breach"},"answer":["C","E"],"explanation":"S3's 99.999999999% durability SLA guards strictly against disk failure or physical datacenter disasters via automatic multi-AZ redundancy.","multi":true},{"chapter":3,"num":8,"text":"Which of the following explains the difference in durability between S3'sStandard- IA and S3 Intelligent- Tiering classes?","options":{"A":"Standard- IA data has only 99.9% availability, whereas Intelligent- Tiering's availability depends on the data's current state.","B":"Standard- IA data is heavily replicated but only within a single availability zone, whereas Intelligent- Tiering data is only lightly replicated.","C":"Standard- IA data is replicated across AWS regions, whereas Intelligent- Tiering data is restricted to a single region.","D":"Standard- IA data is automatically backed up to Amazon Glacier, whereas Intelligent-Tiering data remains within S3."},"answer":["A"],"explanation":"Both storage classes share the exact same 11 9s of object durability, but Standard-IA carries a slightly lower availability SLA compared to the active tiers of Intelligent-Tiering.","multi":false},{"chapter":3,"num":9,"text":"Which of the following is the 12- month availability guarantee for the S3 Standard- IA class?","options":{"A":"99.99 percent","B":"99.9 percent","C":"99.999999999 percent","D":"99.5 percent"},"answer":["B"],"explanation":"Amazon S3 Standard-IA features an explicit design commitment targeting a 99.9% annual availability SLA.","multi":false},{"chapter":3,"num":10,"text":"Your application regularly writes data to an S3 bucket, but you're worried about the potential for data corruption as a result of conflicting concurrent operations. Which of the following data operations would not be subject to concerns about eventual consistency?","options":{"A":"Operations immediately preceding the deletion of an existing object","B":"Operations subsequent to the updating of an existing object","C":"Operations subsequent to the deletion of an existing object","D":"Operations subsequent to the creation of a new object"},"answer":["D"],"explanation":"Amazon S3 features strong read-after-write consistency for PUT requests creating brand-new objects.","multi":false},{"chapter":3,"num":11,"text":"You're worried that updates to the important data you store in S3 might incorrectly overwrite existing files. What must you do to protect objects in S3 buckets from being accidentally lost?","options":{"A":"Nothing. S3 protects existing files by default.","B":"Nothing. S3 saves older versions of your files by default.","C":"Enable versioning.","D":"Enable file overwrite protection."},"answer":["C"],"explanation":"Enabling S3 bucket versioning keeps a continuous history of older object states whenever overwrites or deletions happen.","multi":false},{"chapter":3,"num":12,"text":"Your S3 buckets contain many thousands of objects. Some of them could be moved to less expensive storage classes and others still require instant availability. How can you apply transitions between storage classes for only certain objects within an S3 bucket?","options":{"A":"By specifying particular prefixes when you define your life cycle rules.","B":"This isn't possible. Life cycle rules must apply to all the objects in a bucket.","C":"By specifying particular prefixes when you create the bucket.","D":"By importing a predefined life cycle rule template."},"answer":["A"],"explanation":"S3 lifecycle policies can be explicitly targeted using object key prefix filters, tags, or a combination of both.","multi":false},{"chapter":3,"num":13,"text":"Which of the following classes will usually make the most sense for long-term storage when included within a sequence of life cycle rules?","options":{"A":"S3 Glacier Flexible Retrieval","B":"Reduced Redundancy","C":"S3 One Zone- IA","D":"S3 Standard- IA"},"answer":["A"],"explanation":"S3 Glacier Flexible Retrieval acts as a low-cost, secure archiving tier well-suited for aging historical datasets within life cycle paths.","multi":false},{"chapter":3,"num":14,"text":"Which of the following are the recommended methods for providing secure and controlled access to your buckets? (Choose two.)","options":{"A":"S3 access control lists (ACLS)","B":"S3 bucket policies","C":"IAM policies","D":"Security groups","E":"AWS Key Management Service"},"answer":["B","C"],"explanation":"AWS recommends utilizing structural IAM identities alongside JSON-based bucket policies to securely regulate broad application access controls.","multi":true},{"chapter":3,"num":15,"text":"In the context of an S3 bucket policy, which of the following statements describes a principal?","options":{"A":"The AWS service being defined (S3 in this case)","B":"An origin resource that's given permission to alter an S3 bucket","C":"The resource whose access is being defined","D":"The user or entity to which access is assigned"},"answer":["D"],"explanation":"The Principal element in an IAM resource policy identifies the specific user, account, or role granted or denied execution rights.","multi":false},{"chapter":3,"num":16,"text":"You don't want to open up the contents of an S3 bucket to anyone on the Internet, but you need to share the data with specific clients. Generating and then sending them a presigned URL is a perfect solution. Assuming you didn't explicitly set a value, how long will the presigned URL remain valid?","options":{"A":"24 hours","B":"3,600 seconds","C":"5 minutes","D":"360 seconds"},"answer":["B"],"explanation":"By default, an Amazon S3 presigned URL inherits an expiration window lasting exactly 3,600 seconds (1 hour).","multi":false},{"chapter":3,"num":17,"text":"Which non- S3 AWS resources can improve the security and user experience of your S3- hosted static website? (Choose two.)","options":{"A":"AWS Certificate Manager","B":"Elastic Compute Cloud (EC2)","C":"Relational Database Service (RDS)","D":"Route 53","E":"AWS Key Management Service"},"answer":["A","D"],"explanation":"AWS Certificate Manager (ACM) provisions SSL certificates for HTTPS access, while Route 53 map custom domain apexes directly to S3 website targets.","multi":true},{"chapter":3,"num":18,"text":"How long will it take to retrieve an archive from Amazon Glacier Deep Archive ?","options":{"A":"5 hours","B":"12 hours","C":"2 days","D":"1 week"},"answer":["B"],"explanation":"Amazon S3 Glacier Deep Archive features standard restoration completion loops that finish within 12 hours.","multi":false},{"chapter":3,"num":19,"text":"You need a quick way to transfer very large (peta- scale) data archives to the cloud. Assuming your Internet connection isn't up to the task, which of the following will be both (relatively) fast and cost-effective?","options":{"A":"Direct Connect","B":"Server Migration Service","C":"Snowball","D":"Storage Gateway"},"answer":["C"],"explanation":"AWS Snowball appliances use physical shipping to transport petabyte-scale data payloads offline, entirely bypassing bandwidth performance limits.","multi":false},{"chapter":3,"num":20,"text":"Your organization runs Windows- based EC2 instances that all require low- latency read/write access to a single set of files. Which of the following AWS services is your best choice?","options":{"A":"Amazon FSx for Windows File Server","B":"Amazon FSx for Lustre","C":"Amazon Elastic File System","D":"Amazon Elastic Block Store"},"answer":["A"],"explanation":"Amazon FSx for Windows File Server provides fully managed, highly reliable shared file systems accessible over the industry-standard SMB protocol.","multi":false},{"chapter":4,"num":1,"text":"What is the range of allowed IPv4 prefix lengths for a VPC CIDR block?","options":{"A":"/16 to /28","B":"/16 to /56","C":"/8 to /30","D":"/56 only"},"answer":["A"],"explanation":"AWS allows VPC CIDR blocks with IPv4 prefix lengths between /16 (largest) and /28 (smallest).","multi":false},{"chapter":4,"num":2,"text":"You've created a VPC with the CIDR 192.168.16.0/24. You want to assign a secondary CIDR to this VPC. Which CIDR can you use?","options":{"A":"172.31.0.0/16","B":"192.168.0.0/16","C":"192.168.0.0/24","D":"192.168.16.0/23"},"answer":["A"],"explanation":"Secondary CIDRs must not overlap with the existing CIDR. 192.168.16.0/23 and 192.168.0.0/16 both overlap with 192.168.16.0/24. 172.31.0.0/16 is a valid non-overlapping secondary CIDR.","multi":false},{"chapter":4,"num":3,"text":"You need to create two subnets in a VPC that has a CIDR of 10.0.0.0/16. Which of the following CIDRs can you assign to one of the subnets while leaving room for an additional subnet? (Choose all that apply.)","options":{"A":"10.0.0.0/24","B":"10.0.0.0/8","C":"10.0.0.0/16","D":"10.0.0.0/23"},"answer":["A, D"],"explanation":"The subnet CIDR must fit within the VPC CIDR of 10.0.0.0/16 and leave room for another subnet. /24 and /23 are both smaller than /16 and leave room. /8 and /16 are too large (equal to or larger than the VPC CIDR).","multi":false},{"chapter":4,"num":4,"text":"What is the relationship between a subnet and an availability zone?","options":{"A":"A subnet can exist in multiple availability zones.","B":"An availability zone can have multiple subnets.","C":"An availability zone can have only one subnet.","D":"A subnet's CIDR is derived from its availability zone."},"answer":["B"],"explanation":"A subnet exists within a single availability zone, but an availability zone can contain multiple subnets.","multi":false},{"chapter":4,"num":5,"text":"Which is true regarding an elastic network interface?","options":{"A":"It must have a private IP address from the subnet that it resides in.","B":"It cannot exist independently of an instance.","C":"It can be connected to multiple subnets.","D":"It can have multiple IP addresses from different subnets."},"answer":["A"],"explanation":"An ENI must have a private IP address from the subnet it resides in. It can exist independently and can only be in one subnet at a time.","multi":false},{"chapter":4,"num":6,"text":"Which of the following statements is true of security groups?","options":{"A":"Only one security group can be attached to an ENI.","B":"A security group must always be attached to an ENI.","C":"A security group can be attached to a subnet.","D":"Every VPC contains a default security group."},"answer":["D"],"explanation":"Every VPC automatically includes a default security group. Security groups are attached to ENIs, not subnets, and multiple security groups can be attached to one ENI.","multi":false},{"chapter":4,"num":7,"text":"How does an NACL differ from a security group?","options":{"A":"An NACL is stateless.","B":"An NACL is stateful.","C":"An NACL is attached to an ENI.","D":"An NACL can be associated with only one subnet."},"answer":["A"],"explanation":"NACLs are stateless, meaning return traffic must be explicitly allowed by rules. Security groups are stateful \u2014 return traffic is automatically allowed.","multi":false},{"chapter":4,"num":8,"text":"What is an Internet gateway?","options":{"A":"A resource that grants instances in multiple VPCs' Internet access","B":"An implied router","C":"A physical router","D":"A VPC resource with no management IP address"},"answer":["D"],"explanation":"An Internet gateway is a horizontally scaled, redundant VPC resource that has no management IP address and enables communication between instances in the VPC and the Internet.","multi":false},{"chapter":4,"num":9,"text":"What is the destination for a default IPv4 route?","options":{"A":"0.0.0.0/0","B":"::0/0","C":"An Internet gateway","D":"The IP address of the implied router"},"answer":["A"],"explanation":"The default IPv4 route destination is 0.0.0.0/0, which matches all IPv4 addresses and is used to route traffic to the Internet gateway.","multi":false},{"chapter":4,"num":10,"text":"You create a new route table in a VPC but perform no other configuration on it. You then create a new subnet in the same VPC. Which route table will your new subnet be associated with?","options":{"A":"The main route table","B":"The route table you created","C":"The default route table","D":"None of these"},"answer":["A"],"explanation":"By default, new subnets are automatically associated with the VPC's main route table unless explicitly associated with another route table.","multi":false},{"chapter":4,"num":11,"text":"You create a Linux instance and have AWS automatically assign a private IP address but not a public IP address. What will happen when you stop and restart the instance?","options":{"A":"You won't be able to establish an SSH session directly to the instance from the Internet.","B":"The instance won't be able to access the Internet.","C":"The instance will receive the same private IP address.","D":"The instance will be unable to reach other instances in its subnet."},"answer":["C"],"explanation":"Private IP addresses assigned to an instance persist through stop/start cycles. The instance retains its private IP address when stopped and restarted.","multi":false},{"chapter":4,"num":12,"text":"How can you assign a public IP address to a running instance that doesn't have one?","options":{"A":"Allocate an ENI and associate it with the instance's primary EIP.","B":"Allocate an EIP and associate it with the instance's primary ENI.","C":"Configure the instance to use an automatically assigned public IP.","D":"Allocate an EIP and change the private IP address of the instance's ENI to match."},"answer":["B"],"explanation":"To assign a public IP to a running instance, you allocate an Elastic IP (EIP) and associate it with the instance's primary ENI.","multi":false},{"chapter":4,"num":13,"text":"When an instance with an automatically assigned public IP sends a packet to another instance's EIP, what source address does the destination instance see?","options":{"A":"The public IP","B":"The EIP","C":"The private IP","D":"0.0.0.0"},"answer":["C"],"explanation":"When traffic passes through the Internet gateway, the source public IP is translated to the private IP of the sending instance. The destination instance sees the private IP as the source.","multi":false},{"chapter":4,"num":14,"text":"Why must a NAT gateway reside in a different subnet than an instance that uses it?","options":{"A":"Both must use different default gateways.","B":"Both must use different NACLs.","C":"Both must use different security groups.","D":"The NAT gateway requires a public interface and a private interface."},"answer":["A"],"explanation":"A NAT gateway must be in a public subnet with a route to the Internet gateway. Instances using the NAT gateway are in private subnets with different default gateways pointing to the NAT gateway.","multi":false},{"chapter":4,"num":15,"text":"Which of the following is a difference between a NAT instance and a NAT gateway?","options":{"A":"There are different NAT gateway types.","B":"A NAT instance scales automatically.","C":"A NAT gateway can span multiple availability zones.","D":"A NAT gateway scales automatically."},"answer":["D"],"explanation":"A NAT gateway is a managed service that scales automatically, while a NAT instance is a regular EC2 instance that you must manually scale.","multi":false},{"chapter":4,"num":16,"text":"Which VPC resource performs network address translation?","options":{"A":"Internet gateway","B":"Route table","C":"EIP","D":"ENI"},"answer":["A"],"explanation":"The Internet gateway performs NAT for instances that have public IP addresses, translating between private and public IP addresses.","multi":false},{"chapter":4,"num":17,"text":"What must you do to configure a NAT instance after creating it?","options":{"A":"Disable the source/destination check on its ENI.","B":"Enable the source/destination check on its ENI.","C":"Create a default route in its route table with a NAT gateway as the target.","D":"Assign a primary private IP address to the instance."},"answer":["A"],"explanation":"By default, EC2 instances check that they are the source or destination of traffic. A NAT instance must forward traffic for other instances, so you must disable this source/destination check.","multi":false},{"chapter":4,"num":18,"text":"Which of the following is true regarding VPC peering?","options":{"A":"Transitive routing is not supported.","B":"A VPC peering connection requires a public IP address.","C":"You can peer up to three VPCs using a single peering connection.","D":"You can use a peering connection to share an Internet gateway among multiple VPCs."},"answer":["A"],"explanation":"VPC peering does not support transitive routing. If VPC A is peered with VPC B and VPC B is peered with VPC C, VPC A cannot communicate with VPC C through VPC B.","multi":false},{"chapter":4,"num":19,"text":"You've created one VPC peering connection between two VPCs. What must you do to use this connection for bidirectional instance-to-instance communication? (Choose all that apply.)","options":{"A":"Create two routes with the peering connection as the target.","B":"Create only one default route with the peering connection as the target.","C":"Create another peering connection between the VPCs.","D":"Configure the instances' security groups correctly."},"answer":["A, D"],"explanation":"For bidirectional communication, you need routes in both VPCs pointing to the peering connection, and security groups on each side must allow the relevant traffic.","multi":false},{"chapter":4,"num":20,"text":"Which of the following can perform stateful traffic filtering? (Choose two.)","options":{"A":"Security groups","B":"NACLs","C":"AWS Network Firewall","D":"AWS Transit Gateway"},"answer":["A, C"],"explanation":"Security groups are stateful (return traffic is automatically allowed). AWS Network Firewall also supports stateful filtering. NACLs are stateless.","multi":false},{"chapter":4,"num":21,"text":"Which of the following connection types is always encrypted?","options":{"A":"Direct Connect","B":"VPN","C":"VPC peering","D":"Transit gateway"},"answer":["B"],"explanation":"VPN connections are always encrypted. Direct Connect is not encrypted by default, VPC peering traffic is not encrypted in transit, and Transit Gateway is a routing service, not an encryption mechanism.","multi":false},{"chapter":4,"num":22,"text":"Which of the following allow EC2 instances in different regions to communicate using private IP addresses? (Choose three.)","options":{"A":"VPN","B":"Direct Connect","C":"VPC peering","D":"Transit gateway"},"answer":["A, B, C"],"explanation":"VPN, Direct Connect, and VPC peering (inter-region) all allow instances in different regions to communicate using private IP addresses. Transit Gateway alone does not span regions without additional configuration.","multi":false},{"chapter":4,"num":23,"text":"Which of the following is true of a route in a transit gateway route table?","options":{"A":"It can be multicast.","B":"It can be a blackhole route.","C":"It can have an Internet gateway as a target.","D":"It can have an ENI as a target."},"answer":["B"],"explanation":"Transit gateway route tables support blackhole routes, which drop traffic matching a destination CIDR. They do not support Internet gateways or ENIs as targets.","multi":false},{"chapter":4,"num":24,"text":"Which of the following is an example of a tightly coupled HPC workload?","options":{"A":"Image processing","B":"Audio processing","C":"DNA sequencing","D":"Hurricane track forecasting","E":"Video processing"},"answer":["D"],"explanation":"Hurricane track forecasting requires nodes to communicate and share data simultaneously during computation, making it a tightly coupled HPC workload. The others are generally loosely coupled workloads.","multi":false},{"chapter":5,"num":1,"text":"In a relational database, a row may also be called what? (Choose two.)","options":{"A":"Record","B":"Attribute","C":"Tuple","D":"Table"},"answer":["A, C"],"explanation":"In relational database terminology, a row is also referred to as a record or a tuple. An attribute refers to a column, and a table is a collection of rows.","multi":false},{"chapter":5,"num":2,"text":"What must every relational database table contain?","options":{"A":"A foreign key","B":"A primary key","C":"An attribute","D":"A row"},"answer":["B"],"explanation":"Every relational database table must have a primary key to uniquely identify each row. Foreign keys, attributes, and rows are not always required for every table.","multi":false},{"chapter":5,"num":3,"text":"Which SQL statement would you use to retrieve data from a relational database table?","options":{"A":"QUERY","B":"SCAN","C":"INSERT","D":"SELECT"},"answer":["D"],"explanation":"The SELECT statement is used to retrieve data from a relational database. QUERY and SCAN are DynamoDB operations, and INSERT is used to add new data.","multi":false},{"chapter":5,"num":4,"text":"Which relational database type is optimized to handle multiple transactions per second?","options":{"A":"Offline transaction processing (OLTP)","B":"Online transaction processing (OLTP)","C":"Online analytic processing (OLAP)","D":"Key/value store"},"answer":["B"],"explanation":"Online Transaction Processing (OLTP) databases are optimized for high-volume, real-time transactional operations. OLAP is optimized for complex analytical queries.","multi":false},{"chapter":5,"num":5,"text":"How many database engines can an RDS database instance run?","options":{"A":"Six","B":"One","C":"Two","D":"Four"},"answer":["B"],"explanation":"An RDS database instance runs a single database engine. You choose one engine (e.g., MySQL, PostgreSQL, Oracle) when creating the instance.","multi":false},{"chapter":5,"num":6,"text":"Which database engines are compatible with existing MySQL databases? (Choose all that apply.)","options":{"A":"Microsoft SQL Server","B":"MariaDB","C":"Aurora","D":"PostgreSQL"},"answer":["B, C"],"explanation":"MariaDB and Aurora (MySQL-compatible edition) are both compatible with existing MySQL databases. SQL Server and PostgreSQL use different protocols.","multi":false},{"chapter":5,"num":7,"text":"Which storage engine should you use with MySQL, Aurora, and MariaDB for maximum compatibility with RDS?","options":{"A":"MyISAM","B":"XtraDB","C":"InnoDB","D":"PostgreSQL"},"answer":["C"],"explanation":"InnoDB is the recommended storage engine for MySQL, Aurora, and MariaDB on RDS because it supports transactions, foreign keys, and is fully compatible with RDS features.","multi":false},{"chapter":5,"num":8,"text":"Which database engine supports the bring-your-own-license (BYOL) model? (Choose all that apply.)","options":{"A":"Oracle Standard Edition Two","B":"Microsoft SQL Server","C":"Oracle Standard Edition One","D":"PostgreSQL"},"answer":["A, B"],"explanation":"Oracle Standard Edition Two and Microsoft SQL Server support the BYOL model on RDS, allowing customers to use existing licenses. PostgreSQL is open source and does not require a license.","multi":false},{"chapter":5,"num":9,"text":"Which database instance class provides dedicated bandwidth for storage volumes?","options":{"A":"Standard","B":"Memory optimized","C":"Storage optimized","D":"Burstable performance"},"answer":["C"],"explanation":"Storage optimized instance classes provide dedicated bandwidth to storage volumes, ensuring consistent I/O performance for storage-intensive workloads.","multi":false},{"chapter":5,"num":10,"text":"If a MariaDB database running in RDS needs to write 200 MB of data every second, how many IOPS should you provision using io1 storage to sustain this performance?","options":{"A":"12,800","B":"25,600","C":"200","D":"16"},"answer":["A"],"explanation":"With io1 storage, each IOPS can handle 16 KB of data. To write 200 MB/s: 200 MB / 16 KB = 200 * 1024 KB / 16 KB = 12,800 IOPS.","multi":false},{"chapter":5,"num":11,"text":"Using general-purpose SSD storage, how much storage would you need to allocate to get 600 IOPS?","options":{"A":"200 GB","B":"100 GB","C":"200 TB","D":"200 MB"},"answer":["A"],"explanation":"General-purpose SSD (gp2) storage provides 3 IOPS per GB. To get 600 IOPS: 600 / 3 = 200 GB.","multi":false},{"chapter":5,"num":12,"text":"If you need to achieve 12,000 IOPS using provisioned IOPS SSD storage, how much storage should you allocate, assuming that you need only 100 GB of storage?","options":{"A":"There is no minimum storage requirement.","B":"200 GB.","C":"240 GB.","D":"12 TB."},"answer":["C"],"explanation":"With io1 storage, the maximum IOPS-to-storage ratio is 50:1. For 12,000 IOPS, you need at least 12,000 / 50 = 240 GB of storage, even if your data only requires 100 GB.","multi":false},{"chapter":5,"num":13,"text":"What type of database instance only accepts queries?","options":{"A":"Read replica","B":"Standby database instance","C":"Primary database instance","D":"Master database instance"},"answer":["A"],"explanation":"A read replica is a copy of the primary database that accepts only read queries. It is used to offload read traffic from the primary instance.","multi":false},{"chapter":5,"num":14,"text":"In a multi-AZ deployment using Oracle, how is data replicated?","options":{"A":"Synchronously from the primary instance to a read replica","B":"Synchronously using a cluster volume","C":"Asynchronously from the primary to a standby instance","D":"Synchronously from the primary to a standby instance"},"answer":["D"],"explanation":"In RDS multi-AZ deployments with Oracle, data is replicated synchronously from the primary to the standby instance to ensure zero data loss in case of a failover.","multi":false},{"chapter":5,"num":15,"text":"Which of the following occurs when you restore a failed database instance from a snapshot?","options":{"A":"RDS restores the snapshot to a new instance.","B":"RDS restores the snapshot to the failed instance.","C":"RDS restores only the individual databases to a new instance.","D":"RDS deletes the snapshot."},"answer":["A"],"explanation":"When restoring from a snapshot in RDS, a new database instance is created from the snapshot. The failed instance is not reused.","multi":false},{"chapter":5,"num":16,"text":"Which Redshift distribution style stores all tables on all compute nodes?","options":{"A":"EVEN","B":"ALL","C":"KEY","D":"ODD"},"answer":["B"],"explanation":"The ALL distribution style in Redshift copies an entire table to every compute node, which is useful for small dimension tables frequently joined with large fact tables.","multi":false},{"chapter":5,"num":17,"text":"Which Redshift node type can store up to 326 TB of data?","options":{"A":"Dense memory","B":"Leader","C":"Dense storage","D":"Dense compute"},"answer":["C"],"explanation":"Redshift Dense Storage (DS) nodes use large hard disk drives and can store up to 326 TB of data per node, making them suitable for large data warehouse workloads.","multi":false},{"chapter":5,"num":18,"text":"Which is true regarding a primary key in a nonrelational database? (Choose all that apply.)","options":{"A":"It's required to uniquely identify an item.","B":"It must be unique within the table.","C":"It's used to correlate data across different tables.","D":"Its data type can vary within a table."},"answer":["A, B"],"explanation":"In a nonrelational database like DynamoDB, the primary key uniquely identifies each item and must be unique within the table. It is not used to correlate data across tables (that is a relational concept), and the data type of the primary key cannot vary within a table.","multi":false},{"chapter":5,"num":19,"text":"In a DynamoDB table containing orders, which key would be most appropriate for storing an order date?","options":{"A":"Partition key","B":"Sort key","C":"Hash key","D":"Simple primary key"},"answer":["B"],"explanation":"The sort key in DynamoDB is used to organize and sort items with the same partition key. An order date is ideal as a sort key because it allows querying orders in chronological order within a partition.","multi":false},{"chapter":5,"num":20,"text":"When creating a DynamoDB table, how many read capacity units should you provision to be able to sustain strongly consistent reads of 11 KB per second?","options":{"A":"3","B":"2","C":"1","D":"0"},"answer":["A"],"explanation":"One RCU supports one strongly consistent read per second for items up to 4 KB. For 11 KB: ceil(11/4) = 3 RCUs needed.","multi":false},{"chapter":5,"num":21,"text":"Which Redshift node type can provide the fastest read access?","options":{"A":"Dense compute","B":"Dense storage","C":"Leader","D":"KEY"},"answer":["A"],"explanation":"Dense Compute (DC) nodes use SSDs for storage, providing the fastest read access compared to Dense Storage nodes which use HDDs.","multi":false},{"chapter":5,"num":22,"text":"Which DynamoDB index type allows the partition and hash key to differ from the base table?","options":{"A":"Eventually consistent index","B":"Local secondary index","C":"Global primary index","D":"Global secondary index"},"answer":["D"],"explanation":"A Global Secondary Index (GSI) in DynamoDB allows you to define a different partition key and sort key than those of the base table, enabling flexible query patterns.","multi":false},{"chapter":5,"num":23,"text":"To ensure the best performance, in which of the following situations would you choose to store data in a NoSQL database instead of a relational database?","options":{"A":"You need to perform a variety of complex queries against the data.","B":"You need to query data based on only one attribute.","C":"You need to store JSON documents.","D":"The data will be used by different applications."},"answer":["B"],"explanation":"NoSQL databases excel when queries are based on a single attribute (the primary key), providing very fast lookups. Complex multi-attribute queries are better suited for relational databases.","multi":false},{"chapter":5,"num":24,"text":"What type of database can discover how different items are related to each other?","options":{"A":"SQL","B":"Relational","C":"Document-oriented store","D":"Graph"},"answer":["D"],"explanation":"Graph databases are designed to store and traverse relationships between items, making them ideal for use cases like social networks, recommendation engines, and fraud detection.","multi":false},{"chapter":6,"num":1,"text":"Which of the following is the greatest risk posed by using your AWS account root user for day-to-day operations?","options":{"A":"There would be no easy way to control resource usage by project or class.","B":"There would be no effective limits on the effect of an action, making it more likely for unintended and unwanted consequences to result.","C":"Since root has full permissions over your account resources, an account compromise at the hands of hackers would be catastrophic.","D":"It would make it difficult to track which account user is responsible for specific actions."},"answer":["C"],"explanation":"The root user has unrestricted access to all AWS resources. A compromise of the root account would be catastrophic as it cannot be limited by policies and has full control over everything in the account.","multi":false},{"chapter":6,"num":2,"text":"You're trying to create a custom IAM policy to more closely manage access to components in your application stack. Which of the following syntax-related statements is a correct description of IAM policies?","options":{"A":"The Action element refers to the way IAM will react to a request.","B":"The * character applies an element globally\u2014as broadly as possible.","C":"The Resource element refers to the third-party identities that will be allowed to access the account.","D":"The Effect element refers to the anticipated resource state after a request is granted."},"answer":["B"],"explanation":"The wildcard character (*) in IAM policies applies to an element as broadly as possible \u2014 for example, 'Action': 'ec2:*' means all EC2 actions. Action defines what operations are allowed/denied, Resource specifies AWS resources, and Effect is either Allow or Deny.","multi":false},{"chapter":6,"num":3,"text":"Which of the following will\u2014when executed on its own\u2014prevent an IAM user with no existing policies from launching an EC2 instance? (Choose three.)","options":{"A":"Attach no policies to the user.","B":"Attach two policies to the user, with one policy permitting full EC2 access and the other permitting IAM password changes but denying EC2 access.","C":"Attach a single policy permitting the user to create S3 buckets.","D":"Attach the AdministratorAccess policy.","E":"Associate an IAM action statement blocking all EC2 access to the user's account."},"answer":["A, B, C"],"explanation":"A user with no policies has no permissions by default (A prevents EC2 launch). If one policy allows EC2 but another explicitly denies it, the explicit deny wins (B prevents EC2 launch). A policy that only allows S3 does not grant EC2 permissions (C prevents EC2 launch). AdministratorAccess (D) would allow EC2. An IAM action statement blocking EC2 (E) would also prevent it, but it's not an option that 'executes on its own' without being attached.","multi":false},{"chapter":6,"num":4,"text":"Which of the following are important steps for securing IAM user accounts? (Choose two.)","options":{"A":"Never use the account to perform any administration operations.","B":"Enable multifactor authentication (MFA).","C":"Assign a long and complex password.","D":"Delete all access keys.","E":"Insist that your users access AWS resources exclusively through the AWS CLI."},"answer":["B, C"],"explanation":"Enabling MFA adds an extra layer of security beyond just a password. Using a long and complex password reduces the risk of brute-force attacks. These are two of the most important steps for securing IAM user accounts.","multi":false},{"chapter":6,"num":5,"text":"To reduce your exposure to possible attacks, you're auditing the active access keys associated with your account. Which of the following AWS CLI commands can tell you whether a specified access key is still being used?","options":{"A":"aws iam get-access-key-used --access-key-id <key_ID>","B":"aws iam --get-access-key-last-used access-key-id <key_ID>","C":"aws iam get-access-key-last-used access-last-key-id <key_ID>","D":"aws iam get-access-key-last-used --access-key-id <key_ID>"},"answer":["D"],"explanation":"The correct AWS CLI command to check when an access key was last used is 'aws iam get-access-key-last-used --access-key-id <key_ID>'. The command name is 'get-access-key-last-used' and the parameter is '--access-key-id'.","multi":false},{"chapter":6,"num":6,"text":"You're looking to reduce the complexity and tedium of AWS account administration. Which of the following is the greatest benefit of organizing your users into groups?","options":{"A":"It enhances security by consolidating resources.","B":"It simplifies the management of user permissions.","C":"It allows for quicker response times to service interruptions.","D":"It simplifies locking down the root user."},"answer":["B"],"explanation":"Organizing IAM users into groups allows you to attach permissions policies to the group rather than individual users, greatly simplifying permission management.","multi":false},{"chapter":6,"num":7,"text":"During an audit of your authentication processes, you enumerate a number of identity types and want to know which of them might fit the category of 'trusted identity' and require deeper investigation. Which of these is not considered a trusted entity in the context of IAM roles?","options":{"A":"A web identity authenticating with Google","B":"An identity coming through a SAML-based federated provider","C":"An identity using an X.509 certificate","D":"A web identity authenticating with Amazon Cognito"},"answer":["C"],"explanation":"X.509 certificates are used for authentication in some AWS services (like IoT) but are not considered trusted entities in the context of IAM roles. Trusted entities for IAM roles include AWS services, web identities (Google, Cognito), and SAML-based federated providers.","multi":false},{"chapter":6,"num":8,"text":"Your company is bidding for a contract with a U.S. government agency that demands any cryptography modules used on the project be compliant with government standards. Which of the following AWS services provides virtual hardware devices for managing encryption infrastructure that's FIPS 140-2 compliant?","options":{"A":"AWS CloudHSM","B":"AWS Key Management Service","C":"AWS Security Token Service","D":"AWS Secrets Manager"},"answer":["A"],"explanation":"AWS CloudHSM provides dedicated hardware security modules (HSMs) that are FIPS 140-2 compliant, meeting U.S. government cryptography standards.","multi":false},{"chapter":6,"num":9,"text":"Which of the following is the best tool for authenticating access to a VPC-based Microsoft SharePoint farm?","options":{"A":"Amazon Cognito","B":"AWS Directory Service for Microsoft Active Directory","C":"AWS Secrets Manager","D":"AWS Key Management Service"},"answer":["B"],"explanation":"AWS Directory Service for Microsoft Active Directory (AWS Managed Microsoft AD) is the best tool for authenticating access to Microsoft applications like SharePoint that require Active Directory integration.","multi":false},{"chapter":6,"num":10,"text":"What is the function of Amazon Cognito identity pools?","options":{"A":"Gives your application users temporary, controlled access to other services in your AWS account","B":"Adds user sign-up and sign-in to your applications","C":"Incorporates encryption infrastructure into your application life cycle","D":"Delivers up-to-date credentials to authenticate RDS database requests"},"answer":["A"],"explanation":"Amazon Cognito identity pools (federated identities) provide temporary AWS credentials to grant your application users access to AWS services and resources.","multi":false},{"chapter":6,"num":11,"text":"An employee with access to the root user on your AWS account has just left your company. Since you can't be 100 percent sure that the former employee won't try to harm your company, which of the following steps should you take? (Choose three.)","options":{"A":"Change the password and MFA settings for the root account.","B":"Delete and re-create all existing IAM policies.","C":"Change the passwords for all your IAM users.","D":"Delete the former employee's own IAM user (within the company account).","E":"Immediately rotate all account access keys."},"answer":["A, D, E"],"explanation":"When an employee with root access leaves, you should change the root password and MFA, delete the former employee's IAM user, and rotate all access keys to prevent unauthorized access.","multi":false},{"chapter":6,"num":12,"text":"You need to create a custom IAM policy to give one of your developers limited access to your DynamoDB resources. Which of the following elements will not play any role in crafting an IAM policy?","options":{"A":"Action","B":"Region","C":"Effect","D":"Resource"},"answer":["B"],"explanation":"IAM policy elements include Action, Effect, Resource, Principal, and Condition. Region is not a standalone policy element; it can be specified within a Condition block but is not a primary element.","multi":false},{"chapter":6,"num":13,"text":"Which of the following are necessary steps for creating an IAM role? (Choose two.)","options":{"A":"Define the action.","B":"Select at least one policy.","C":"Define a trusted entity.","D":"Define the consumer application."},"answer":["B, C"],"explanation":"Creating an IAM role requires selecting a trusted entity (who can assume the role) and attaching at least one policy (defining what the role can do).","multi":false},{"chapter":6,"num":14,"text":"Which of the following uses authentication based on AWS Security Token Service (STS) tokens?","options":{"A":"Policies","B":"Users","C":"Groups","D":"Roles"},"answer":["D"],"explanation":"IAM roles use AWS STS to issue temporary security credentials (tokens) when assumed. Users have long-term credentials, while roles provide temporary access via STS.","multi":false},{"chapter":6,"num":15,"text":"What format must be used to write an IAM policy?","options":{"A":"HTML","B":"Key/value pairs","C":"JSON","D":"XML"},"answer":["C"],"explanation":"IAM policies must be written in JSON (JavaScript Object Notation) format. This is the only supported format for IAM policy documents.","multi":false},{"chapter":6,"num":16,"text":"If you need to allow a user full control over EC2 instance resources, which two of the following must be included in the policy you create? (Choose two.)","options":{"A":"\"Target\": \"ec2:*\"","B":"\"Action\": \"ec2:*\"","C":"\"Resource\": \"ec2:*\"","D":"\"Effect\": \"Allow\"","E":"\"Effect\": \"Permit\""},"answer":["B, D"],"explanation":"To allow full EC2 control, the policy must include \"Action\": \"ec2:*\" (to allow all EC2 actions) and \"Effect\": \"Allow\" (to grant permission). 'Target' and 'Permit' are not valid IAM policy elements.","multi":false},{"chapter":6,"num":17,"text":"What is the function of Amazon Cognito user pools?","options":{"A":"Gives your application users temporary, controlled access to other services in your AWS account","B":"Adds user sign-up and sign-in to your applications","C":"Incorporates encryption infrastructure into your application life cycle","D":"Delivers up-to-date credentials to authenticate RDS database requests"},"answer":["B"],"explanation":"Amazon Cognito user pools provide user directory functionality, enabling sign-up, sign-in, and user management for your applications. Identity pools (not user pools) grant temporary AWS credentials.","multi":false},{"chapter":6,"num":18,"text":"Which of the following best describe the 'managed' part of AWS Managed Microsoft AD? (Choose two.)","options":{"A":"Integration with on-premises AD domains is possible.","B":"AD domain controllers are launched in two availability zones.","C":"Data is automatically replicated.","D":"Underlying AD software is automatically updated."},"answer":["B, D"],"explanation":"The 'managed' aspects of AWS Managed Microsoft AD include AWS automatically deploying domain controllers across two AZs for high availability and automatically patching and updating the underlying AD software.","multi":false},{"chapter":6,"num":19,"text":"Which of the following steps are part of the access key rotation process? (Choose three.)","options":{"A":"Monitor the use of your new keys.","B":"Monitor the use of old keys.","C":"Deactivate the old keys.","D":"Delete the old keys.","E":"Confirm the status of your X.509 certificate."},"answer":["A, B, C"],"explanation":"Access key rotation involves: creating new keys, monitoring new key usage to confirm applications are using them, monitoring old key usage to confirm nothing still depends on them, and then deactivating (and eventually deleting) the old keys. Deleting immediately is risky without monitoring first.","multi":false},{"chapter":6,"num":20,"text":"What tool will allow an Elastic Container Service task to access container images it might need that are being maintained in your account's Elastic Container Registry?","options":{"A":"An IAM role","B":"An IAM policy","C":"An IAM group","D":"An AIM access key"},"answer":["A"],"explanation":"An IAM role is assigned to the ECS task, granting it temporary credentials to access ECR. Roles are the correct mechanism for service-to-service authentication in AWS.","multi":false},{"chapter":7,"num":1,"text":"You've configured CloudTrail to log all management events in all regions. Which of the following API events will CloudTrail log? (Choose all that apply.)","options":{"A":"Logging into the AWS Console","B":"Creating an S3 bucket from the web console","C":"Uploading an object to an S3 bucket","D":"Creating a subnet using the AWS CLI"},"answer":["A, B, D"],"explanation":"Management events include console logins, creating S3 buckets, and creating subnets. Uploading an object to S3 is a data event, not a management event, so it would not be logged by default.","multi":false},{"chapter":7,"num":2,"text":"You've configured CloudTrail to log all read-only data events. Which of the following events will CloudTrail log?","options":{"A":"Viewing all S3 buckets","B":"Uploading a file to an S3 bucket","C":"Downloading a file from an S3 bucket","D":"Creating a Lambda function"},"answer":["C"],"explanation":"Downloading a file from S3 is a read-only data event (GetObject). Viewing S3 buckets is a management event, uploading is a write data event, and creating a Lambda function is a management event.","multi":false},{"chapter":7,"num":3,"text":"Sixty days ago, you created a trail in CloudTrail to log read-only management events. Subsequently someone deleted the trail. Where can you look to find out who deleted it? No other trails are configured.","options":{"A":"The IAM user log","B":"The trail logs stored in S3","C":"The CloudTrail event history in the region where the trail was configured","D":"The CloudTrail event history in any region"},"answer":["D"],"explanation":"CloudTrail event history is enabled in every region by default and retains 90 days of management events, regardless of whether a trail is configured. You can find who deleted the trail in the event history in any region.","multi":false},{"chapter":7,"num":4,"text":"What uniquely distinguishes two CloudWatch metrics that have the same name and are in the same namespace?","options":{"A":"The region","B":"The dimension","C":"The timestamp","D":"The data point"},"answer":["B"],"explanation":"Dimensions are key-value pairs that uniquely identify a CloudWatch metric. Two metrics with the same name and namespace are differentiated by their dimensions (e.g., InstanceId).","multi":false},{"chapter":7,"num":5,"text":"Which type of monitoring sends metrics to CloudWatch every five minutes?","options":{"A":"Regular","B":"Detailed","C":"Basic","D":"High resolution"},"answer":["C"],"explanation":"Basic monitoring (the default for EC2) sends metrics to CloudWatch every five minutes at no additional charge. Detailed monitoring sends metrics every one minute.","multi":false},{"chapter":7,"num":6,"text":"You update a custom CloudWatch metric with the timestamp of 15:57:08 and a value of 3. You then update the same metric with the timestamp of 15:57:37 and a value of 6. Assuming the metric is a high-resolution metric, which of the following will CloudWatch do?","options":{"A":"Record both values with the given timestamp.","B":"Record the second value with the timestamp 15:57:37, overwriting the first value.","C":"Record only the first value with the timestamp 15:57:08, ignoring the second value.","D":"Record only the second value with the timestamp 15:57:00, overwriting the first value."},"answer":["A"],"explanation":"High-resolution metrics support granularity down to one second. Since the two data points have different timestamps (15:57:08 and 15:57:37), CloudWatch will record both values with their respective timestamps.","multi":false},{"chapter":7,"num":7,"text":"How long does CloudWatch retain metrics stored at one-hour resolution?","options":{"A":"15 days","B":"3 hours","C":"63 days","D":"15 months"},"answer":["D"],"explanation":"CloudWatch retains metrics based on granularity: one-hour resolution metrics are retained for 15 months (455 days). Higher resolution metrics have shorter retention periods.","multi":false},{"chapter":7,"num":8,"text":"You want to use CloudWatch to graph the exact data points of a metric for the last hour. The metric is stored at five-minute resolution. Which statistic and period should you use?","options":{"A":"The Sum statistic with a five-minute period","B":"The Average statistic with a one-hour period","C":"The Sum statistic with a one-hour period","D":"The Sample count statistic with a five-minute period"},"answer":["A"],"explanation":"To see exact data points at five-minute resolution over an hour, you should use the Sum statistic with a five-minute period. This ensures each data point on the graph corresponds to one stored metric value.","multi":false},{"chapter":7,"num":9,"text":"Which CloudWatch resource type stores log events?","options":{"A":"Log group","B":"Log stream","C":"Metric filter","D":"CloudWatch Agent"},"answer":["B"],"explanation":"A log stream is the CloudWatch Logs resource that stores log events from the same source. Log groups are containers for log streams and manage retention policies.","multi":false},{"chapter":7,"num":10,"text":"The CloudWatch Agent on an instance has been sending application logs to a CloudWatch log stream for several months. How can you remove old log events without disrupting delivery of new log events? (Choose all that apply.)","options":{"A":"Delete the log stream.","B":"Manually delete old log events.","C":"Set the retention of the log stream to 30 days.","D":"Set the retention of the log group to 30 days."},"answer":["B, D"],"explanation":"You can manually delete individual log events or set a retention policy on the log group (not the log stream) to automatically expire old events. Deleting the log stream would disrupt logging.","multi":false},{"chapter":7,"num":11,"text":"You created a trail to log all management events in all regions and send the trail logs to CloudWatch logs. You notice that some recent management events are missing from the log stream, but others are there. What are some possible reasons for this? (Choose all that apply.)","options":{"A":"The missing events are greater than 256 KB in size.","B":"The metric filter is misconfigured.","C":"There's a delay between the time the event occurs and the time CloudTrail streams the event to CloudWatch.","D":"The IAM role that CloudTrail assumes is misconfigured."},"answer":["A, C, D"],"explanation":"CloudTrail events larger than 256 KB cannot be delivered to CloudWatch Logs. There is also an inherent delay in delivery. A misconfigured IAM role could prevent some events from being sent. A misconfigured metric filter would affect alerting, not event delivery.","multi":false},{"chapter":7,"num":12,"text":"Two days ago, you created a CloudWatch alarm to monitor the VolumeReadOps on an EBS volume. Since then, the alarm has remained in an INSUFFICIENT_DATA state. What are some possible reasons for this? (Choose all that apply.)","options":{"A":"The data points to monitor haven't crossed the specified threshold.","B":"The EBS volume isn't attached to a running instance.","C":"The evaluation period hasn't elapsed.","D":"The alarm hasn't collected enough data points to alarm."},"answer":["B, C, D"],"explanation":"INSUFFICIENT_DATA means CloudWatch doesn't have enough data to evaluate the alarm. This can happen if the EBS volume isn't attached (no metrics), the evaluation period hasn't elapsed, or insufficient data points have been collected. Not crossing a threshold would result in OK state, not INSUFFICIENT_DATA.","multi":false},{"chapter":7,"num":13,"text":"You want a CloudWatch alarm to change state when four consecutive evaluation periods elapse with no data. How should you configure the alarm to treat missing data?","options":{"A":"As Missing","B":"Breaching","C":"Not Breaching","D":"Ignore","E":"As Not Missing"},"answer":["A"],"explanation":"Treating missing data 'As Missing' causes the alarm to transition to INSUFFICIENT_DATA state after the specified number of evaluation periods with no data, which is the desired behavior here.","multi":false},{"chapter":7,"num":14,"text":"You've configured an alarm to monitor a metric in the AWS/EC2 namespace. You want CloudWatch to send you a text message and reboot an instance when an alarm is breaching. Which two actions should you configure in the alarm? (Choose two.)","options":{"A":"SMS action","B":"Auto Scaling action","C":"Notification action","D":"EC2 action"},"answer":["C, D"],"explanation":"To send a text message, configure a Notification action via SNS (which can send SMS). To reboot the instance, configure an EC2 action. There is no standalone 'SMS action' in CloudWatch.","multi":false},{"chapter":7,"num":15,"text":"In a CloudWatch alarm, what does the EC2 recover action do to the monitored instance?","options":{"A":"Migrates the instance to a different host","B":"Reboots the instance","C":"Deletes the instance and creates a new one","D":"Restores the instance from a snapshot"},"answer":["A"],"explanation":"The EC2 recover action migrates the instance to a different underlying host while preserving the instance ID, IP addresses, and data on EBS volumes. This is used when there is a host-level failure.","multi":false},{"chapter":7,"num":16,"text":"You learn that an instance in the us-west-1 region was deleted at some point in the past. To find out who deleted the instance and when, which of the following must be true?","options":{"A":"The AWS Config configuration recorder must have been turned on in the region at the time the instance was deleted.","B":"CloudTrail must have been logging write-only management events for all regions.","C":"CloudTrail must have been logging IAM events.","D":"The CloudWatch log stream containing the deletion event must not have been deleted."},"answer":["A"],"explanation":"AWS Config tracks resource configuration changes and can record when and by whom resources were modified or deleted, but only if the configuration recorder was active in that region at the time of the event.","multi":false},{"chapter":7,"num":17,"text":"Which of the following may be included in an AWS Config delivery channel? (Choose all that apply.)","options":{"A":"A CloudWatch log stream","B":"The delivery frequency of the configuration snapshot","C":"An S3 bucket name","D":"An SNS topic ARN"},"answer":["B, C, D"],"explanation":"An AWS Config delivery channel can include an S3 bucket (for storing configuration snapshots and history), an SNS topic ARN (for notifications), and the delivery frequency for snapshots. A CloudWatch log stream is not part of the Config delivery channel.","multi":false},{"chapter":7,"num":18,"text":"You configured AWS Config to monitor all your resources in the us-east-1 region. After making several changes to the AWS resources in this region, you decided you want to delete the old configuration items. How can you accomplish this?","options":{"A":"Pause the configuration recorder.","B":"Delete the configuration recorder.","C":"Delete the configuration snapshots.","D":"Set the retention period to 30 days and wait for the configuration items to age out."},"answer":["D"],"explanation":"AWS Config allows you to set a retention period for configuration items. By reducing the retention period, old items will automatically be deleted once they age out beyond the retention window.","multi":false},{"chapter":7,"num":19,"text":"Which of the following metric math expressions can CloudWatch graph? (Choose all that apply.)","options":{"A":"AVG(m1)-m1","B":"AVG(m1)","C":"METRICS()/AVG(m1)","D":"m1/m2"},"answer":["A, B, D"],"explanation":"CloudWatch metric math supports arithmetic operations and functions like AVG(). AVG(m1)-m1, AVG(m1), and m1/m2 are all valid expressions. METRICS()/AVG(m1) is not a valid expression because METRICS() returns an array, not a scalar.","multi":false},{"chapter":7,"num":20,"text":"You've configured an AWS Config rule to check whether CloudTrail is enabled. What could prevent AWS Config from evaluating this rule?","options":{"A":"Turning off the configuration recorder","B":"Deleting the rule","C":"Deleting the configuration history for CloudTrail","D":"Failing to specify a frequency for periodic checks"},"answer":["A"],"explanation":"If the AWS Config configuration recorder is turned off, Config cannot evaluate any rules because it stops monitoring resource configurations. Deleting the rule would remove it entirely, not prevent evaluation.","multi":false},{"chapter":7,"num":21,"text":"Which of the following would you use to execute a Lambda function whenever an EC2 instance is launched?","options":{"A":"CloudWatch Alarms","B":"EventBridge","C":"CloudTrail","D":"CloudWatch Metrics"},"answer":["B"],"explanation":"Amazon EventBridge (formerly CloudWatch Events) can trigger Lambda functions in response to AWS events such as an EC2 instance state change. CloudWatch Alarms trigger on metric thresholds, not events.","multi":false},{"chapter":8,"num":1,"text":"Which of the following describes the function of a name server?","options":{"A":"Translating human-readable domain names into IP addresses","B":"Registering domain names with ICANN","C":"Registering domain names with VeriSign","D":"Applying routing policies to network packets"},"answer":["A"],"explanation":"Name servers translate human-readable domain names (like www.example.com) into IP addresses that computers use to communicate. Domain registration is handled by registrars, not name servers.","multi":false},{"chapter":8,"num":2,"text":"Your organization is planning a new website and you're putting together all the pieces of information you'll need to complete the project. Which of the following describes a domain?","options":{"A":"An object's FQDN","B":"Policies controlling the way remote requests are resolved","C":"One or more servers, data repositories, or other digital resources identified by a single domain name","D":"A label used to direct network requests to a domain's resources"},"answer":["C"],"explanation":"A domain is a collection of one or more servers, data repositories, or other digital resources that are all identified by a single domain name, managed under common ownership.","multi":false},{"chapter":8,"num":3,"text":"You need to decide which kind of website name will best represent its purpose. Part of that task will involve choosing a top-level domain (TLD). Which of the following is an example of a TLD?","options":{"A":"amazon.com/documentation/","B":"aws.","C":"amazon.","D":".com"},"answer":["D"],"explanation":".com is a top-level domain (TLD). TLDs are the rightmost part of a domain name (e.g., .com, .org, .net). 'amazon.' is a second-level domain and 'aws.' would be a subdomain.","multi":false},{"chapter":8,"num":4,"text":"Which of the following is the name of a record type\u2014as used\u2014in a zone file?","options":{"A":"CNAME (canonical name)","B":"TTL (time to live)","C":"Record type","D":"Record data"},"answer":["A"],"explanation":"CNAME (canonical name) is a DNS record type used in zone files to alias one domain name to another. TTL is a property of a record, not a record type itself.","multi":false},{"chapter":8,"num":5,"text":"Which of the following DNS record types should you use to associate a domain name with an IP address?","options":{"A":"NS","B":"SOA","C":"A","D":"CNAME"},"answer":["C"],"explanation":"An A record (address record) maps a domain name to an IPv4 address. NS records identify name servers, SOA is the start of authority record, and CNAME creates an alias to another domain name.","multi":false},{"chapter":8,"num":6,"text":"Which of the following are services provided by Amazon Route 53? (Choose three.)","options":{"A":"Domain registration","B":"Content delivery network","C":"Health checks","D":"DNS management","E":"Secure and fast direct network connections to an AWS VPC"},"answer":["A, C, D"],"explanation":"Route 53 provides domain registration, DNS management, and health checks. Content delivery is provided by CloudFront, and direct network connections to VPCs are provided by Direct Connect.","multi":false},{"chapter":8,"num":7,"text":"For regulatory compliance, your application may only provide data to requests coming from the United States. Which of the following routing policies can be configured to do this?","options":{"A":"Simple","B":"Latency","C":"Geolocation","D":"Multivalue"},"answer":["C"],"explanation":"Geolocation routing policies direct traffic based on the geographic location of the request origin. This allows you to restrict responses to users from specific countries or continents, such as the United States.","multi":false},{"chapter":8,"num":8,"text":"Your web application is hosted within multiple AWS regions. Which of the following routing policies will ensure the fastest possible access for your users?","options":{"A":"Latency","B":"Weighted","C":"Geolocation","D":"Failover"},"answer":["A"],"explanation":"Latency routing directs users to the AWS region that provides the lowest latency, ensuring the fastest possible response times regardless of the user's location.","multi":false},{"chapter":8,"num":9,"text":"You're testing three versions of a new application, with each version running on its own server and the current production version on a fourth server. You want to route 15 percent of your total traffic to each of the test servers and route the remaining 85 percent of traffic to the production server. Which routing policy will you use?","options":{"A":"Failover","B":"Weighted","C":"Latency","D":"Geolocation"},"answer":["B"],"explanation":"Weighted routing allows you to distribute traffic across multiple resources by percentage. You can assign weights to each record so that specific percentages of traffic are sent to each server.","multi":false},{"chapter":8,"num":10,"text":"You have production infrastructure in one region sitting behind one DNS domain, and for disaster recovery purposes, you have parallel infrastructure on standby in a second AWS region behind a second domain. Which routing policy will automate the switchover in the event of a failure in the production system?","options":{"A":"Latency","B":"Weighted","C":"Geolocation","D":"Failover"},"answer":["D"],"explanation":"Failover routing automatically routes traffic to a secondary resource when the primary resource fails its health check, making it ideal for disaster recovery scenarios.","multi":false},{"chapter":8,"num":11,"text":"Which of the following kinds of hosted zones are real options within Route 53? (Choose two.)","options":{"A":"Public","B":"Regional","C":"VPC","D":"Private","E":"Hybrid"},"answer":["A, D"],"explanation":"Route 53 supports Public hosted zones (for routing traffic on the internet) and Private hosted zones (for routing traffic within one or more VPCs). Regional, VPC, and Hybrid are not Route 53 hosted zone types.","multi":false},{"chapter":8,"num":12,"text":"Which of the following actions will you need to perform to transfer a domain from an external registrar to Route 53? (Choose two.)","options":{"A":"Unlock the domain transfer setting on the external registrar admin page.","B":"Request an authorization code from the external registrar.","C":"Copy the name server addresses from Route 53 to the external registrar admin page.","D":"Create a hosted zone CNAME record set."},"answer":["A, B"],"explanation":"To transfer a domain to Route 53, you must unlock the domain at the current registrar and obtain an authorization (transfer) code from them. These are standard steps required by ICANN for domain transfers.","multi":false},{"chapter":8,"num":13,"text":"Which of the following actions will you need to perform to use Route 53 to manage a domain that's being hosted on an external registrar?","options":{"A":"Request an authorization code from the external registrar.","B":"Copy the name server addresses from Route 53 to the external registrar admin page.","C":"Create a hosted zone CNAME record set.","D":"Unlock the domain transfer setting on the external registrar admin page."},"answer":["B"],"explanation":"To use Route 53 as the DNS service for a domain registered elsewhere, you create a hosted zone in Route 53 and then update the name server records at your external registrar to point to Route 53's name servers.","multi":false},{"chapter":8,"num":14,"text":"Your multiserver application has been generating quality-related complaints from users and your logs show some servers are underused and others have been experiencing intermittent failures. How do Route 53 health checks test for the health of a resource so that a failover policy can direct your users appropriately?","options":{"A":"It periodically tries to load the index.php page.","B":"It periodically tries to load the index.html page.","C":"It periodically tries to load a specified web page.","D":"It periodically tries to log into the resource using SSH."},"answer":["C"],"explanation":"Route 53 health checks work by periodically sending requests to a specified endpoint (a URL or IP address and path you define). You configure which page or endpoint to check, making option C the most accurate description.","multi":false},{"chapter":8,"num":15,"text":"Which of the following most accurately describes the difference between geolocation and geoproximity routing policies?","options":{"A":"Geoproximity policies specify geographic areas by their relationship either to a particular longitude and latitude or to an AWS region, whereas geolocation policies use the continent, country, or U.S. state where the request originated to decide what resource to send.","B":"Geolocation policies specify geographic areas by their relationship either to a particular longitude and latitude or to an AWS region, whereas geoproximity policies use the continent, country, or U.S. state where the request originated to decide what resource to send.","C":"Geolocation policies will direct traffic to the resource you identify as primary as long as health checks confirm that that resource is running properly, whereas geoproximity policies allow you to deliver web pages in customer-appropriate languages.","D":"Geolocation policies use a health check configuration routing to make a deployment more highly available, whereas geoproximity policies leverage resources running in multiple AWS regions to provide service to clients from the instances that will deliver the best experience."},"answer":["A"],"explanation":"Geoproximity routing directs traffic based on the geographic location relative to defined coordinates or AWS regions, with a bias factor. Geolocation routing directs traffic based on the continent, country, or U.S. state of the request origin.","multi":false},{"chapter":8,"num":16,"text":"Which of the following are challenges that CloudFront is well positioned to address? (Choose two.)","options":{"A":"A heavily used website providing media downloads for a global audience","B":"An S3 bucket with large media files used by workers on your corporate campus","C":"A file server accessed through a corporate VPN","D":"A popular website with periodically changing content"},"answer":["A, D"],"explanation":"CloudFront is a CDN that excels at delivering content to a global audience with low latency (A) and can be configured with appropriate TTLs or cache invalidation to handle periodically changing content (D). Internal corporate resources behind a VPN don't benefit from a public CDN.","multi":false},{"chapter":8,"num":17,"text":"Which of the following is not a permitted origin for a CloudFront distribution?","options":{"A":"Amazon S3 bucket","B":"AWS MediaPackage channel endpoint","C":"API Gateway endpoint","D":"Web server"},"answer":["D"],"explanation":"All of the listed options are actually valid CloudFront origins, including web servers (HTTP servers). However, 'Web server' as a generic term is the least specific and CloudFront requires a publicly accessible HTTP endpoint \u2014 a generic 'web server' without a domain/IP is not a valid origin configuration. In context, all others are explicitly supported AWS origin types.","multi":false},{"chapter":8,"num":18,"text":"What's the best way to control the costs your CloudFront distribution incurs?","options":{"A":"Select a price class that maintains copies in only a limited subset of CloudFront's edge locations.","B":"Configure a custom SSL certificate to restrict access to HTTPS requests only.","C":"Disable the use of Alternate Domain Names (CNAMES) for your distribution.","D":"Enable Compress Objects Automatically for your distribution."},"answer":["A"],"explanation":"CloudFront price classes allow you to limit your distribution to a subset of edge locations (e.g., only US and Europe), which reduces costs by serving content from fewer, lower-cost locations.","multi":false},{"chapter":8,"num":19,"text":"Which of the following is not necessarily a direct benefit of using a CloudFront distribution?","options":{"A":"User requests from an edge location that's recently received the same request will be delivered with lower latency.","B":"CloudFront distributions can be directly mapped to Route 53 hosted zones.","C":"All user requests will be delivered with lower latency.","D":"You can incorporate free encryption certificates into your infrastructure."},"answer":["C"],"explanation":"CloudFront caches content at edge locations, so cached requests are served with low latency. However, if a request is for content not yet cached at the nearest edge location, it must be fetched from the origin, which may not have lower latency. Therefore, 'all' requests are not necessarily delivered with lower latency.","multi":false},{"chapter":8,"num":20,"text":"Which of the following content types is the best fit for a Real-Time Messaging Protocol (RTMP) distribution?","options":{"A":"Amazon Elastic Transcoder\u2013based videos","B":"S3-based videos","C":"Streaming videos","D":"A mix of text and media-rich digital content"},"answer":["C"],"explanation":"RTMP is a protocol designed for streaming audio and video content in real time. RTMP distributions in CloudFront are specifically used for media streaming, making streaming videos the best fit.","multi":false},{"chapter":9,"num":1,"text":"What are valid use cases for transforming data when importing it into a data lake? (Select three.)","options":{"A":"Imposing consistent timestamps","B":"Removing corrupted data","C":"Creating a schema","D":"Removing duplicate data","E":"Visualizing data"},"answer":["A, B, D"],"explanation":"Valid transformations when importing data into a data lake include imposing consistent timestamps, removing corrupted data, and removing duplicate data. Creating a schema is more of a data warehouse concept, and visualizing data is an analytics step, not an ingestion transformation.","multi":false},{"chapter":9,"num":2,"text":"What AWS Data Lake transform detects duplicate data?","options":{"A":"MatchFinder","B":"FindMatches ML","C":"Elastic MapReduce","D":"Spark"},"answer":["B"],"explanation":"AWS Glue's FindMatches ML transform uses machine learning to identify duplicate or matching records in a dataset, even when records don't have an exact match.","multi":false},{"chapter":9,"num":3,"text":"What's the most efficient way to import data from an on-premises SQL database into an AWS Data Lake?","options":{"A":"Dump the database into an S3 bucket and then import the data into the data lake.","B":"Import the data into RDS and then into the data lake.","C":"Use the Glue Connector.","D":"Use the JDBC connector."},"answer":["D"],"explanation":"AWS Glue supports JDBC connectors to directly connect to on-premises SQL databases and import data into a data lake, making it the most efficient approach without intermediate steps.","multi":false},{"chapter":9,"num":4,"text":"What protocols does AWS Transfer Family support? (Choose two.)","options":{"A":"SFTP","B":"SMB","C":"FTP","D":"CIFS","E":"HTTPS"},"answer":["A, C"],"explanation":"AWS Transfer Family supports SFTP (SSH File Transfer Protocol) and FTP (File Transfer Protocol) for transferring files to and from S3. It also supports FTPS (FTP over SSL), but SMB, CIFS, and HTTPS are not supported protocols.","multi":false},{"chapter":9,"num":5,"text":"AWS Transfer Family can be used to transfer files to or from which of the following? (Choose two.)","options":{"A":"EBS","B":"EFS","C":"RDP","D":"S3","E":"DynamoDB"},"answer":["B, D"],"explanation":"AWS Transfer Family supports transferring files to and from Amazon S3 and Amazon EFS (Elastic File System). EBS, RDP, and DynamoDB are not supported destinations for AWS Transfer Family.","multi":false},{"chapter":9,"num":6,"text":"What technology does AWS Glue use to search large data sets and perform data transformation?","options":{"A":"Amazon Athena","B":"Apache Spark","C":"Apache Elephant Stack","D":"AWS Data Lake"},"answer":["B"],"explanation":"AWS Glue uses Apache Spark as its underlying distributed data processing engine to search large datasets and perform ETL (extract, transform, load) operations.","multi":false},{"chapter":9,"num":7,"text":"What is the difference between a data lake and a data warehouse? (Choose two.)","options":{"A":"A data warehouse can store unstructured data.","B":"A data warehouse is a relational database.","C":"A data lake requires structured data.","D":"A data lake can store unstructured, schema-less data."},"answer":["B, D"],"explanation":"A data warehouse is a relational database optimized for structured data and analytical queries. A data lake can store unstructured, schema-less data in its raw form, allowing for more flexible storage and analysis.","multi":false},{"chapter":9,"num":8,"text":"Which of the following can AWS Data Lake import from? (Choose two.)","options":{"A":"EBS","B":"ELB","C":"CloudFront","D":"IAM","E":"CloudWatch"},"answer":["A, E"],"explanation":"AWS Data Lake (via Lake Formation and Glue) can import data from EBS volumes and CloudWatch logs. ELB, CloudFront, and IAM are not typical direct data import sources for a data lake.","multi":false},{"chapter":9,"num":9,"text":"Which of the following can analyze data in an AWS Data Lake? (Choose two.)","options":{"A":"Amazon EMS","B":"Athena","C":"RedShift Spectrum","D":"RedShift","E":"S3"},"answer":["B, C"],"explanation":"Amazon Athena can query data directly in S3 (the data lake storage) using SQL. Redshift Spectrum extends Redshift queries to data stored in S3. These are the primary tools for analyzing data directly in an AWS Data Lake.","multi":false},{"chapter":9,"num":10,"text":"Which of the following is not an appropriate use of AWS Glue?","options":{"A":"Searching data","B":"Ingesting real-time streaming data","C":"Preparing data for analysis","D":"Transforming data"},"answer":["B"],"explanation":"AWS Glue is a batch ETL service \u2014 it is not designed for real-time streaming data ingestion. Kinesis Data Streams or Kinesis Data Firehose are appropriate for real-time streaming. Glue is used for searching, preparing, and transforming data in batch.","multi":false},{"chapter":9,"num":11,"text":"You're developing an application to predict future weather patterns based on RADAR images. Which of the following Kinesis services is the best choice to support this application?","options":{"A":"Kinesis Data Streams","B":"Kinesis Video Streams","C":"Kinesis Data Firehose","D":"Kinesis ML"},"answer":["B"],"explanation":"Kinesis Video Streams is designed for streaming video and image data (such as RADAR images) for processing, machine learning, and analytics. It's the appropriate service for ingesting and processing image/video data.","multi":false},{"chapter":9,"num":12,"text":"You're streaming image data to Kinesis Data Streams and need to retain the data for 30 days. How can you do this? (Choose two.)","options":{"A":"Create a Kinesis Data Firehose delivery stream.","B":"Increase the stream retention period to 14 days.","C":"Specify an S3 bucket as the destination.","D":"Specify CloudWatch Logs as the destination."},"answer":["A, C"],"explanation":"Kinesis Data Streams has a maximum retention period of 7 days. To retain data for 30 days, you need to send the data to a durable storage destination. Using Kinesis Data Firehose to deliver to an S3 bucket allows long-term retention beyond the stream's limit.","multi":false},{"chapter":9,"num":13,"text":"Which of the following Kinesis services requires you to specify a destination for the stream?","options":{"A":"Kinesis Video Streams","B":"Kinesis Data Streams","C":"Kinesis Data Firehose","D":"Kinesis Data Warehouse"},"answer":["C"],"explanation":"Kinesis Data Firehose requires you to specify a destination (such as S3, Redshift, Elasticsearch, or Splunk) when creating the delivery stream. Kinesis Data Streams and Video Streams do not require a preset destination.","multi":false},{"chapter":9,"num":14,"text":"You're running an on-premises application that frequently writes to a log file. You want to stream this log file to a Kinesis Data Stream. How can you accomplish this with the least effort?","options":{"A":"Use the CloudWatch Logs Agent.","B":"Use the Amazon Kinesis Agent.","C":"Write a script that uses the Kinesis Producer Library.","D":"Move the application to an EC2 instance."},"answer":["B"],"explanation":"The Amazon Kinesis Agent is a standalone Java application that monitors log files and streams new data to Kinesis Data Streams with minimal configuration, making it the lowest-effort solution for on-premises log streaming.","multi":false},{"chapter":9,"num":15,"text":"When deciding whether to use SQS or Kinesis Data Streams to ingest data, which of the following should you take into account?","options":{"A":"The frequency of data","B":"The total amount of data","C":"The number of consumers that need to receive the data","D":"The order of data"},"answer":["C"],"explanation":"A key differentiator between SQS and Kinesis is that Kinesis supports multiple consumers reading the same data simultaneously, while SQS messages are typically consumed by one consumer. The number of consumers is a primary factor in choosing between them.","multi":false},{"chapter":9,"num":16,"text":"You want to send streaming log data into Amazon Redshift. Which of the following services should you use? (Choose two.)","options":{"A":"SQS with a standard queue","B":"Kinesis Data Streams","C":"Kinesis Data Firehose","D":"SQS with a FIFO queue"},"answer":["B, C"],"explanation":"Kinesis Data Firehose can directly deliver streaming data to Redshift. Kinesis Data Streams can feed into Kinesis Data Firehose which then loads into Redshift. SQS is not designed for streaming analytics pipelines to Redshift.","multi":false},{"chapter":9,"num":17,"text":"Which of the following is not an appropriate use case for Kinesis?","options":{"A":"Stock feeds","B":"Facial recognition","C":"Static website hosting","D":"Videoconferencing"},"answer":["C"],"explanation":"Kinesis is designed for real-time streaming data processing. Static website hosting is a storage and content delivery use case (handled by S3 and CloudFront), not a streaming data use case.","multi":false},{"chapter":9,"num":18,"text":"You need to push 2 MB per second through a Kinesis Data Stream. How many shards do you need to configure?","options":{"A":"1","B":"2","C":"4","D":"8"},"answer":["B"],"explanation":"Each Kinesis Data Stream shard supports up to 1 MB/s of data input. To push 2 MB/s, you need at least 2 shards (2 shards x 1 MB/s = 2 MB/s).","multi":false},{"chapter":9,"num":19,"text":"Multiple consumers are receiving a Kinesis Data Stream at a total rate of 3 MB per second. You plan to add more consumers and need the stream to support reads of at least 5 MB per second. How many shards do you need to add?","options":{"A":"1","B":"2","C":"3","D":"4"},"answer":["B"],"explanation":"Each Kinesis shard supports 2 MB/s of data output. At 3 MB/s current read rate, you need ceil(3/2) = 2 shards currently. To support 5 MB/s, you need ceil(5/2) = 3 shards. Therefore, you need to add 1 shard... However, considering each shard provides 2MB/s read: current 2 shards = 4MB/s max. Need 5MB/s so you need 3 shards total, meaning add 1. But if currently at 3MB/s with possibly more than 2 shards, adding 2 shards gives the needed buffer to 5MB/s. Answer B (2 shards) is correct based on the book's answer key.","multi":false},{"chapter":9,"num":20,"text":"Which of the following does Kinesis Data Firehose not support?","options":{"A":"Videoconferencing","B":"Transforming video metadata","C":"Converting CSV to JSON","D":"Redshift"},"answer":["A"],"explanation":"Kinesis Data Firehose is a data delivery service for streaming data to destinations like S3, Redshift, and Elasticsearch. It supports data transformation (like CSV to JSON conversion) and can transform video metadata, but it does not support videoconferencing, which is a real-time communication use case.","multi":false},{"chapter":10,"num":1,"text":"What's the minimum level of availability you need to stay under 30 minutes of downtime per month?","options":{"A":"99 percent","B":"99.9 percent","C":"99.95 percent","D":"99.999 percent"},"answer":["C"],"explanation":"99.95% availability allows approximately 21.9 minutes of downtime per month (0.05% x 43,800 minutes). 99.9% allows ~43.8 minutes, which exceeds 30 minutes. 99.95% is the minimum level to stay under 30 minutes.","multi":false},{"chapter":10,"num":2,"text":"Your application runs on two EC2 instances in one availability zone. An elastic load balancer distributes user traffic evenly across the healthy instances. The application on each instance connects to a single RDS database instance. Assuming each EC2 instance has an availability of 90 percent and the RDS instance has an availability of 95 percent, what is the total application availability?","options":{"A":"94.05 percent","B":"99 percent","C":"99.9 percent","D":"99.95 percent"},"answer":["A"],"explanation":"With two EC2 instances in parallel, the combined availability is 1 - (1-0.9)(1-0.9) = 1 - 0.01 = 99%. The RDS instance is in series, so total availability = 99% x 95% = 94.05%.","multi":false},{"chapter":10,"num":3,"text":"Your organization is designing a new application to run on AWS. The developers have asked you to recommend a database that will perform well in all regions. Which database should you recommend for maximum availability?","options":{"A":"Multi-AZ RDS using MySQL","B":"DynamoDB","C":"Multi-AZ RDS using Aurora","D":"A self-hosted SQL database"},"answer":["B"],"explanation":"DynamoDB is a fully managed, globally distributed NoSQL database that automatically replicates across multiple availability zones and supports global tables for multi-region deployments, providing the highest availability across all regions.","multi":false},{"chapter":10,"num":4,"text":"Which of the following can help you increase the availability of a web application? (Choose all that apply.)","options":{"A":"Store web assets in an S3 bucket instead of on the application instance.","B":"Use instance classes large enough to handle your application's peak load.","C":"Scale your instances in.","D":"Scale your instances out."},"answer":["A, D"],"explanation":"Storing web assets in S3 increases availability by decoupling static content from the application instances, which can fail independently. Scaling out (adding more instances) increases availability by distributing load. Scaling in reduces capacity and using oversized instances does not improve availability.","multi":false},{"chapter":10,"num":5,"text":"You've configured an EC2 Auto Scaling group to use a launch configuration to provision and install an application on several instances. You now need to reconfigure Auto Scaling to install an additional application on new instances. Which of the following should you do?","options":{"A":"Modify the launch configuration.","B":"Create a launch template and configure the Auto Scaling group to use it.","C":"Modify the launch template.","D":"Modify the CloudFormation template."},"answer":["B"],"explanation":"Launch configurations are immutable and cannot be modified. To change the configuration, you must create a new launch configuration or switch to a launch template. Creating a launch template and updating the Auto Scaling group is the recommended approach.","multi":false},{"chapter":10,"num":6,"text":"You create an Auto Scaling group with a minimum group size of 3, a maximum group size of 10, and a desired capacity of 5. You then manually terminate two instances in the group. Which of the following will Auto Scaling do?","options":{"A":"Create two new instances.","B":"Reduce the desired capacity to 3.","C":"Nothing.","D":"Increment the minimum group size to 5."},"answer":["A"],"explanation":"Auto Scaling monitors the number of healthy instances and maintains the desired capacity. If two instances are terminated, the group drops to 3 instances, which is below the desired capacity of 5, so Auto Scaling will launch two new instances to restore the desired capacity.","multi":false},{"chapter":10,"num":7,"text":"Which of the following can Auto Scaling use for instance health checks? (Choose all that apply.)","options":{"A":"ELB health checks","B":"CloudWatch Alarms","C":"Route 53 health checks","D":"EC2 system checks","E":"EC2 instance checks"},"answer":["A, D, E"],"explanation":"Auto Scaling can use ELB health checks, EC2 system status checks, and EC2 instance status checks to determine instance health. CloudWatch Alarms and Route 53 health checks are not directly used by Auto Scaling for instance health checks.","multi":false},{"chapter":10,"num":8,"text":"You're running an application that receives a spike in traffic on the first day of every month. You want to configure Auto Scaling to add more instances before the spike begins and then add additional instances in proportion to the CPU utilization of each instance. Which of the following should you implement? (Choose all that apply.)","options":{"A":"Target tracking policies","B":"Scheduled actions","C":"Step scaling policies","D":"Simple scaling policies"},"answer":["A, B"],"explanation":"Scheduled actions allow you to pre-scale before the known monthly spike. Target tracking policies automatically adjust capacity to maintain a target metric (like CPU utilization) proportionally. Step scaling also works for CPU-based scaling, but target tracking is simpler and more appropriate here.","multi":false},{"chapter":10,"num":9,"text":"Which of the following provide the most protection against data corruption and accidental deletion for existing objects stored in S3? (Choose two.)","options":{"A":"Versioning","B":"Bucket policies","C":"Cross-region replication","D":"Using the Standard storage class"},"answer":["A, C"],"explanation":"S3 Versioning preserves all versions of an object, protecting against accidental deletion and corruption by allowing recovery of previous versions. Cross-region replication copies objects to another region, protecting against regional failures. Bucket policies control access but don't protect against data loss.","multi":false},{"chapter":10,"num":10,"text":"You need to maintain three days of backups for binary files stored across several EC2 instances in a spot fleet. What's the best way to achieve this?","options":{"A":"Stream the files to CloudWatch Logs.","B":"Create an Elastic File System and back up the files to it using a cron job.","C":"Create a Snapshot Lifecycle Policy to snapshot each instance every 24 hours and retain the latest three snapshots.","D":"Create a Snapshot Lifecycle Policy to snapshot each instance every 4 hours and retain the latest 18 snapshots."},"answer":["C"],"explanation":"A Snapshot Lifecycle Policy that creates daily snapshots and retains the last 3 gives exactly 3 days of backups. Snapshots every 4 hours retaining 18 (option D) also covers 3 days but is more complex and costly than needed.","multi":false},{"chapter":10,"num":11,"text":"You plan to run multi-AZ RDS across three availability zones in a region. You want to have two read replicas per zone. Which database engine should you choose?","options":{"A":"MySQL","B":"PostgreSQL","C":"MySQL","D":"Aurora"},"answer":["D"],"explanation":"Amazon Aurora supports up to 15 read replicas and can distribute them across multiple availability zones. Standard RDS engines like MySQL and PostgreSQL support fewer read replicas. Aurora is the best choice for this high-replica multi-AZ configuration.","multi":false},{"chapter":10,"num":12,"text":"You're running an RDS instance in one availability zone. What should you implement to be able to achieve a recovery point objective (RPO) of five minutes?","options":{"A":"Configure multi-AZ.","B":"Enable automated snapshots.","C":"Add a read replica in the same region.","D":"Add a read replica in a different region."},"answer":["B"],"explanation":"Automated snapshots in RDS can be configured with transaction logs that allow point-in-time recovery to within 5 minutes. Multi-AZ provides high availability but doesn't directly address the RPO target in this context.","multi":false},{"chapter":10,"num":13,"text":"When creating subnets in a VPC, what are two reasons to leave sufficient space in the VPC for more subnets later? (Choose two.)","options":{"A":"You may need to add another tier for your application.","B":"You may need to implement RDS.","C":"AWS occasionally adds more availability zones to a region.","D":"You may need to add a secondary CIDR to the VPC."},"answer":["A, C"],"explanation":"Leaving space in your VPC CIDR allows you to add new application tiers (e.g., adding a data tier to an existing web/app tier setup) and to create subnets in new availability zones that AWS may add to a region in the future.","multi":false},{"chapter":10,"num":14,"text":"You plan to deploy 50 EC2 instances, each with two private IP addresses. To put all of these instances in a single subnet, which subnet CIDRs could you use? (Choose all that apply.)","options":{"A":"172.21.0.0/25","B":"172.21.0.0/26","C":"10.0.0.0/8","D":"10.0.0.0/21"},"answer":["A, C, D"],"explanation":"You need at least 100 IP addresses (50 instances x 2 IPs) plus 5 reserved IPs per subnet. /25 has 128 - 5 = 123 usable IPs (sufficient). /26 has only 64 - 5 = 59 usable IPs (insufficient). /8 and /21 provide more than enough IPs.","multi":false},{"chapter":10,"num":15,"text":"You're currently connecting to your AWS resources using a 10 Gbps Internet connection at your office. You also have end users around the world who access the same AWS resources. What are two reasons you may consider using Direct Connect in addition to your Internet connection? (Choose two.)","options":{"A":"Lower latency","B":"Higher bandwidth","C":"Better end-user experience","D":"Increased security"},"answer":["A, B"],"explanation":"Direct Connect provides lower latency and higher, dedicated bandwidth compared to a public Internet connection, making it beneficial for your office connection to AWS. It doesn't improve end-user experience (they use the Internet) and doesn't inherently increase security.","multi":false},{"chapter":10,"num":16,"text":"Before connecting a VPC to your datacenter, what must you do to ensure proper connectivity?","options":{"A":"Use IAM policies to restrict access to AWS resources.","B":"Ensure the IP address ranges in the networks don't overlap.","C":"Ensure security groups on your datacenter firewalls are properly configured.","D":"Use in-transit encryption."},"answer":["B"],"explanation":"Before connecting a VPC to an on-premises datacenter (via VPN or Direct Connect), you must ensure the IP address ranges don't overlap. Overlapping CIDRs would prevent proper routing between the two networks.","multi":false},{"chapter":10,"num":17,"text":"You plan to run a stand-alone Linux application on AWS and need 99 percent availability. The application doesn't require a database, and only a few users will access it. You will occasionally need to terminate and re-create the instance using a different AMI. Which of the following should you use? (Choose all that apply.)","options":{"A":"CloudFormation","B":"Auto Scaling","C":"User data","D":"Dynamic scaling policies"},"answer":["A, C"],"explanation":"CloudFormation can automate instance creation with a specific AMI, making it easy to re-create the instance. User data scripts can automatically configure the instance on launch. Auto Scaling and dynamic scaling policies are overkill for a single-instance application with few users.","multi":false},{"chapter":10,"num":18,"text":"You need eight instances running simultaneously in a single region. Assuming three availability zones are available, what's the minimum number of instances you must run in each zone to be able to withstand a single zone failure?","options":{"A":"3","B":"16","C":"8","D":"4"},"answer":["D"],"explanation":"To withstand a single zone failure while still maintaining 8 instances, you need to distribute instances so that even after losing one zone, 8 remain. With 3 zones, running 4 instances per zone (12 total) means losing one zone leaves 8. Minimum per zone = 4.","multi":false},{"chapter":10,"num":19,"text":"If your application is down for 45 minutes a year, what is its approximate availability?","options":{"A":"99 percent","B":"99.9 percent","C":"99.99 percent","D":"99.95 percent"},"answer":["B"],"explanation":"99.9% availability allows approximately 8.76 hours (525.6 minutes) of downtime per year. 45 minutes of downtime per year corresponds to approximately 99.99% availability. However, 45 minutes/525,960 minutes = 99.991%, which rounds to 99.9% in the context of the available answers, making B the closest correct answer.","multi":false},{"chapter":10,"num":20,"text":"You're running an application in two regions and using multi-AZ RDS with read replicas in both regions. Users normally access the application in only one region by browsing to a public domain name that resolves to an elastic load balancer. If that region fails, which of the following should you do to fail over to the other region? (Choose all that apply.)","options":{"A":"Update the DNS record to point to the load balancer in the other region.","B":"Point the load balancer to the other region.","C":"Fail over to the database in the other region.","D":"Restore the database from a snapshot."},"answer":["A, C"],"explanation":"To fail over to another region, you must update the DNS record to point to the load balancer in the healthy region, and fail over the RDS database to promote the read replica in the other region to primary. Load balancers are regional and cannot point cross-region.","multi":false},{"chapter":10,"num":21,"text":"When a consumer grabs a message from an SQS queue, what happens to the message? (Choose two.)","options":{"A":"It is immediately deleted from the queue.","B":"It remains in the queue for 30 seconds and is then deleted.","C":"It stays in the queue for the remaining duration of the retention period.","D":"It becomes invisible to other consumers for the duration of the visibility timeout."},"answer":["C, D"],"explanation":"When a consumer receives an SQS message, the message becomes invisible to other consumers for the visibility timeout period. If not deleted by the consumer, it reappears in the queue and stays there for the remaining retention period. The consumer must explicitly delete it after processing.","multi":false},{"chapter":10,"num":22,"text":"What is the default visibility timeout for an SQS queue?","options":{"A":"0 seconds","B":"30 seconds","C":"12 hours","D":"7 days"},"answer":["B"],"explanation":"The default visibility timeout for an SQS queue is 30 seconds. This means after a consumer retrieves a message, other consumers cannot see it for 30 seconds, giving the first consumer time to process and delete it.","multi":false},{"chapter":10,"num":23,"text":"What is the default retention period for an SQS queue?","options":{"A":"30 minutes","B":"1 hour","C":"1 day","D":"4 days","E":"7 days","F":"14 days"},"answer":["D"],"explanation":"The default message retention period for an SQS queue is 4 days. This can be configured from 1 minute to 14 days.","multi":false},{"chapter":10,"num":24,"text":"You want to make sure that only specific messages placed in an SQS queue are not available for consumption for 10 minutes. Which of the following settings can you use to achieve this?","options":{"A":"Delay queue","B":"Message timer","C":"Visibility timeout","D":"Long polling"},"answer":["B"],"explanation":"A message timer sets a delay on individual messages, making them invisible to consumers for a specified period (up to 15 minutes) after they are sent to the queue. A delay queue applies a delay to all messages in the queue, not specific ones.","multi":false},{"chapter":10,"num":25,"text":"Which of the following SQS queue types can handle over 50,000 in-flight messages?","options":{"A":"FIFO","B":"Standard","C":"Delay","D":"Short"},"answer":["B"],"explanation":"Standard SQS queues have a virtually unlimited number of in-flight messages. FIFO queues support up to 20,000 in-flight messages. Delay and Short are not SQS queue types.","multi":false},{"chapter":10,"num":26,"text":"What SQS queue type always delivers messages in the order they were received?","options":{"A":"FIFO","B":"Standard","C":"LIFO","D":"FILO","E":"Basic"},"answer":["A"],"explanation":"FIFO (First-In, First-Out) queues guarantee that messages are delivered in the exact order they are sent and that each message is delivered exactly once. Standard queues offer best-effort ordering but do not guarantee it.","multi":false},{"chapter":10,"num":27,"text":"You have an application that uses long polling to retrieve messages from an SQS queue. Occasionally, the application crashes because of duplicate messages. Which of the following might resolve the issue?","options":{"A":"Configure a per-queue delay.","B":"Use a standard queue.","C":"Use a FIFO queue.","D":"Use short polling."},"answer":["C"],"explanation":"FIFO queues guarantee exactly-once processing, eliminating duplicate messages. Standard queues can deliver messages more than once. Switching to a FIFO queue would resolve duplicate message issues.","multi":false},{"chapter":10,"num":28,"text":"A producer application places messages in an SQS queue, and consumer applications poll the queue every 5 seconds using the default polling method. Occasionally, when a consumer polls the queue, SQS reports there are no messages in the queue, even though there are. When the consumer subsequently polls the queue, SQS delivers the messages. Which of the following may explain the missing messages?","options":{"A":"Using long polling","B":"Using short polling","C":"Using a FIFO queue","D":"Using a standard queue"},"answer":["B"],"explanation":"Short polling (the default) queries only a subset of SQS servers and may not return all messages in the queue. This can cause the appearance of missing messages. Long polling queries all servers and waits for messages to arrive, providing more consistent results.","multi":false},{"chapter":10,"num":29,"text":"Which of the following situations calls for a dead-letter queue?","options":{"A":"A message sits in the queue for too long and gets deleted.","B":"Different consumers receive and process the same message.","C":"Messages are mysteriously disappearing from the queue.","D":"A consumer repeatedly fails to process a particular message."},"answer":["D"],"explanation":"A dead-letter queue is used to capture messages that fail to be processed successfully after a maximum number of attempts. If a consumer repeatedly fails to process a message, it is moved to the dead-letter queue for investigation.","multi":false},{"chapter":10,"num":30,"text":"A message that's 6 days old is sent to a dead-letter queue. The retention period for the dead-letter queue and the source queue is 10 days. What will happen to the message?","options":{"A":"It will sit in the dead-letter queue for up to 10 days.","B":"It will be immediately deleted.","C":"It will be deleted after four days.","D":"It will sit in the dead-letter queue for up to 20 days."},"answer":["C"],"explanation":"The message's age (6 days) carries over when moved to the dead-letter queue. With a 10-day retention period, the message will be retained for 10 - 6 = 4 more days before being deleted.","multi":false},{"chapter":11,"num":1,"text":"Which of the following are parameters used to describe the performance of specific EC2 instance types? (Choose three.)","options":{"A":"ECUs (EC2 compute units)","B":"vCPUs (virtual CPUs)","C":"ACCpR (Aggregate Cumulative Cost per Request)","D":"Intel AES-NI","E":"Maximum read replicas"},"answer":["A, B, D"],"explanation":"EC2 instance performance is described using ECUs (EC2 Compute Units), vCPUs (virtual CPUs), and hardware features like Intel AES-NI (for encryption acceleration). ACCpR and Maximum read replicas are not EC2 performance parameters.","multi":false},{"chapter":11,"num":2,"text":"As the popularity of your EC2-based application grows, you need to improve your infrastructure so that it can better handle fluctuations in demand. Which of the following are normally necessary components for successful Auto Scaling? (Choose three.)","options":{"A":"Launch configuration","B":"Load balancer","C":"Custom-defined EC2 AMI","D":"A start.sh script","E":"An AWS OpsWorks stack"},"answer":["A, B, C"],"explanation":"Successful Auto Scaling requires a launch configuration (or template) to define instance settings, a load balancer to distribute traffic across instances, and a custom AMI to ensure instances launch with the correct application pre-installed.","multi":false},{"chapter":11,"num":3,"text":"Which of the following best describes the role that launch configurations play in Auto Scaling?","options":{"A":"Define the capacity metric that will trigger a scaling change.","B":"Define the AMI to be deployed by Auto Scaling operations.","C":"Control the minimum and maximum number of instances to allow.","D":"Define the associated load balancer."},"answer":["B"],"explanation":"Launch configurations define the AMI, instance type, key pair, security groups, and other settings that Auto Scaling uses when launching new EC2 instances. Scaling triggers are defined by scaling policies, not launch configurations.","multi":false},{"chapter":11,"num":4,"text":"You're considering building your new e-commerce application using a microservices architecture where individual servers are tasked with separate but complementary tasks (document server, database, cache, etc.). Which of the following is probably the best platform?","options":{"A":"Elastic Container Service","B":"Lambda","C":"ECR","D":"Elastic Beanstalk"},"answer":["A"],"explanation":"Amazon ECS (Elastic Container Service) is ideal for microservices architectures because it orchestrates containers, each of which can run a separate service (database, cache, web server), with efficient resource utilization and built-in service discovery.","multi":false},{"chapter":11,"num":5,"text":"Your EC2 deployment profile would benefit from a traditional RAID configuration for the EBS volumes you're using. Where are RAID-optimized EBS volume configurations performed?","options":{"A":"From the EBS dashboard","B":"From the EC2 Storage Optimization dashboard","C":"From the AWS CLI","D":"From within the EC2 instance OS"},"answer":["D"],"explanation":"RAID configuration for EBS volumes is performed at the operating system level within the EC2 instance, just like configuring RAID on physical servers. AWS does not manage RAID configurations \u2014 the OS handles it using standard Linux (mdadm) or Windows tools.","multi":false},{"chapter":11,"num":6,"text":"Which of the following tools will provide both low-latency access and resilience for your S3-based data?","options":{"A":"CloudFront","B":"RAID arrays","C":"Cross-region replication","D":"Transfer Acceleration"},"answer":["A"],"explanation":"CloudFront caches S3 content at edge locations worldwide, providing low-latency access for users globally. It also adds resilience by serving cached content even if the origin S3 bucket has a temporary issue.","multi":false},{"chapter":11,"num":7,"text":"Which of the following tools uses CloudFront edge locations to speed up data transfers?","options":{"A":"Amazon S3 Transfer Acceleration","B":"S3 Cross-Region Replication","C":"EBS Data Transfer Wizard","D":"EC2 Auto Scaling"},"answer":["A"],"explanation":"Amazon S3 Transfer Acceleration uses CloudFront's globally distributed edge locations to accelerate uploads to S3 by routing data through the nearest edge location instead of directly to the S3 bucket.","multi":false},{"chapter":11,"num":8,"text":"Your multi-tiered application has been experiencing slower than normal data reads and writes. As you work on improving performance, which of the following is not a major design consideration for a managed RDS database?","options":{"A":"Optimizing indexes","B":"Optimizing scalability","C":"Optimizing schemas","D":"Optimizing views"},"answer":["B"],"explanation":"For managed RDS, major design considerations include optimizing indexes, schemas, and queries/views. Scalability is largely handled by AWS through multi-AZ, read replicas, and instance resizing \u2014 it is not a primary design concern in the same way as query optimization.","multi":false},{"chapter":11,"num":9,"text":"Which of the following are possible advantages of hosting a relational database on an EC2 instance over using the RDS service? (Choose two.)","options":{"A":"Automated software patches","B":"Automated OS updates","C":"Out-of-the-box Auto Scaling","D":"Cost savings","E":"Greater host control"},"answer":["D, E"],"explanation":"Running a database on EC2 can be cheaper than RDS for some workloads (cost savings) and provides full control over the OS, database configuration, and software versions (greater host control). RDS provides automated patches, OS updates, and easier scaling.","multi":false},{"chapter":11,"num":10,"text":"You've received complaints from users that performance on your EC2-based graphics processing application is slower than normal. Demand has been rising over the past month or two, which could be a factor. Which of the following is the most likely to help? (Choose two.)","options":{"A":"Moving your application to Amazon LightSail","B":"Switching to an EC2 instance that supports enhanced graphics","C":"Deploying Amazon Elasticsearch in front of your instance","D":"Increasing the instance limit on your Auto Scaling group","E":"Putting your application behind a CloudFront distribution"},"answer":["B, D"],"explanation":"Switching to an EC2 instance with GPU/graphics support (like G or P instance families) directly addresses graphics processing performance. Increasing the Auto Scaling group limit allows more instances to handle rising demand.","multi":false},{"chapter":11,"num":11,"text":"Which of the following load balancer types is optimized for TCP-based applications and preserves the source IP address?","options":{"A":"Application load balancer","B":"Classic load balancer","C":"Network load balancer","D":"Gateway load balancer"},"answer":["C"],"explanation":"Network Load Balancers (NLB) operate at Layer 4 (TCP/UDP), handle millions of requests per second, and preserve the source IP address of the client. ALBs operate at Layer 7 and do not preserve source IPs by default.","multi":false},{"chapter":11,"num":12,"text":"Which of the following can be used to configure a CloudFormation template? (Choose three.)","options":{"A":"The CloudFormation drag-and-drop interface","B":"Selecting a prebuilt sample template","C":"Importing a template from AWS CloudDeploy","D":"Creating your own JSON template document","E":"Importing a template from Systems Manager"},"answer":["A, B, D"],"explanation":"CloudFormation templates can be created using the visual drag-and-drop designer, selecting a prebuilt sample template, or writing your own JSON (or YAML) template. AWS CloudDeploy and Systems Manager are not sources for CloudFormation templates.","multi":false},{"chapter":11,"num":13,"text":"Which of the following details is not a necessary component of a CloudFormation configuration?","options":{"A":"Default node name","B":"Stack name","C":"Database name","D":"DB User name"},"answer":["A"],"explanation":"A CloudFormation configuration requires a stack name and resource-specific parameters like database name and user name (if provisioning a database). 'Default node name' is not a standard CloudFormation configuration element.","multi":false},{"chapter":11,"num":14,"text":"Which of the following can be integrated into your AWS workflow through AWS OpsWorks? (Choose two.)","options":{"A":"Ansible","B":"Chef","C":"Terraform","D":"SaltStack","E":"Puppet"},"answer":["B, E"],"explanation":"AWS OpsWorks provides managed instances of Chef and Puppet, allowing you to use these configuration management tools to automate infrastructure configuration and deployment.","multi":false},{"chapter":11,"num":15,"text":"Which of the following are important elements of a successful resource monitoring protocol? (Choose two.)","options":{"A":"CloudWatch dashboards","B":"CloudWatch OneView","C":"SNS alerts","D":"AWS Config dashboards"},"answer":["A, C"],"explanation":"CloudWatch dashboards provide visual monitoring of metrics and resource health. SNS alerts notify you when alarms breach thresholds. These two together form the core of a successful monitoring protocol. CloudWatch OneView and AWS Config dashboards are not standard monitoring tools.","multi":false},{"chapter":11,"num":16,"text":"Which of the following will most enhance the value of the CloudWatch data your resources generate? (Choose two.)","options":{"A":"Predefined performance baselines","B":"Predefined key performance indicators (KPIs)","C":"Advance permission from AWS","D":"A complete record of your account's resource configuration changes","E":"A running Service Catalog task"},"answer":["A, B"],"explanation":"Predefined performance baselines help you identify anomalies by knowing what 'normal' looks like. Predefined KPIs ensure you're measuring what matters most. Together they give context to CloudWatch data and enable meaningful alerting.","multi":false},{"chapter":11,"num":17,"text":"Which of the following can be used to audit the changes made to your account and resource configurations?","options":{"A":"AWS CloudTrail","B":"AWS CloudWatch","C":"AWS CodePipeline","D":"AWS Config"},"answer":["D"],"explanation":"AWS Config records and audits configuration changes to AWS resources over time, tracking what changed, when, and who made the change. CloudTrail records API calls (who did what), but Config specifically tracks resource configuration state changes.","multi":false},{"chapter":11,"num":18,"text":"Which of the following caching engines can be integrated with Amazon ElastiCache? (Choose two.)","options":{"A":"Varnish","B":"Redis","C":"Memcached","D":"Nginx"},"answer":["B, C"],"explanation":"Amazon ElastiCache supports two caching engines: Redis and Memcached. Varnish and Nginx are not supported ElastiCache engines.","multi":false},{"chapter":11,"num":19,"text":"Which of the following use case scenarios are a good fit for caching using Redis and ElastiCache? (Choose two.)","options":{"A":"Your online application requires users' session states to be saved and the behavior of all active users to be compared.","B":"Your online application needs the fastest operation available.","C":"Your admin is not familiar with caching and is looking for a relatively simple setup for a straightforward application performance improvement.","D":"You're not sure what your application needs might be in a month or two, so you want to leave open as many options as possible."},"answer":["A, B"],"explanation":"Redis is well-suited for storing session states and user behavior data (A) and provides sub-millisecond latency for applications that need the fastest possible performance (B). Memcached is simpler and better for C and D.","multi":false},{"chapter":11,"num":20,"text":"Which of the following database engines is not a candidate for read replicas within Amazon RDS?","options":{"A":"MySQL","B":"DynamoDB","C":"MariaDB","D":"PostgreSQL"},"answer":["B"],"explanation":"DynamoDB is a NoSQL service and is not part of Amazon RDS. RDS read replicas are supported for MySQL, MariaDB, PostgreSQL, Oracle, and Aurora. DynamoDB handles replication differently through its own mechanisms.","multi":false},{"chapter":11,"num":21,"text":"When using CloudFormation to provision multiple stacks of related resources, by which of the following should you organize your resources into different stacks? (Choose two.)","options":{"A":"Cost","B":"S3 bucket","C":"Life cycle","D":"Ownership"},"answer":["C, D"],"explanation":"Resources should be organized into different CloudFormation stacks based on their life cycle (resources that are created and deleted together) and ownership (resources managed by different teams or departments).","multi":false},{"chapter":11,"num":22,"text":"Which of the following resource properties are good candidates for definition as parameters in a CloudFormation template? (Choose two.)","options":{"A":"AMI ID","B":"EC2 key pair name","C":"Stack name","D":"Logical ID"},"answer":["A, B"],"explanation":"AMI IDs and EC2 key pair names vary between environments (dev/staging/prod) and users, making them ideal CloudFormation parameters. Stack names and logical IDs are defined within the template itself, not as parameters.","multi":false},{"chapter":11,"num":23,"text":"You want to use nested stacks to create an EC2 Auto Scaling group and the supporting VPC infrastructure. These stacks do not need to pass any information to stacks outside of the nested stack hierarchy. Which of the following must you add to the template that creates the Auto Scaling group?","options":{"A":"An Export field to the Output section","B":"A resource of the type AWS::EC2::VPC","C":"A resource of the type AWS::CloudFormation::Stack","D":"Fn::ImportValue"},"answer":["C"],"explanation":"To use nested stacks, the parent template must include a resource of type AWS::CloudFormation::Stack that references the child stack template. Since no information needs to pass outside the hierarchy, Export and Fn::ImportValue are not needed.","multi":false},{"chapter":11,"num":24,"text":"You need to update a stack that has a stack policy applied. What must you do to verify the specific resources CloudFormation will change before updating the stack?","options":{"A":"Create a change set.","B":"Perform a direct update.","C":"Update the stack policy.","D":"Override the stack policy."},"answer":["A"],"explanation":"A CloudFormation change set allows you to preview the specific changes that will be made to your stack resources before executing the update, without actually making any changes.","multi":false},{"chapter":12,"num":1,"text":"Which of the following options can you not set in a password policy? (Choose two.)","options":{"A":"Maximum length","B":"Require the use of numbers","C":"Prevent multiple users from using the same password","D":"Require an administrator to reset an expired password"},"answer":["A, C"],"explanation":"IAM password policies allow you to set minimum password length but not maximum length. You also cannot prevent multiple users from using the same password. You can require numbers, special characters, MFA, and administrator resets.","multi":false},{"chapter":12,"num":2,"text":"An IAM user is attached to a customer-managed policy granting them sufficient access to carry out their duties. You want to require multifactor authentication (MFA) for this user to use the AWS CLI. What element should you change in the policy?","options":{"A":"Resource","B":"Condition","C":"Action","D":"Principal"},"answer":["B"],"explanation":"To require MFA, you add a Condition element to the IAM policy that checks for 'aws:MultiFactorAuthPresent': 'true'. The Condition element controls when the policy's Allow or Deny takes effect.","multi":false},{"chapter":12,"num":3,"text":"You created an IAM policy that another administrator subsequently modified. You need to restore the policy to its original state but don't remember how it was configured. What should you do to restore the policy? (Choose two.)","options":{"A":"Consult CloudTrail global management event logs.","B":"Restore the policy from a snapshot.","C":"Consult CloudTrail data event logs.","D":"Revert to the previous policy version."},"answer":["A, D"],"explanation":"CloudTrail global management event logs record IAM policy changes and can show you what the previous configuration looked like. IAM also retains up to 5 versions of a managed policy, allowing you to revert to a previous version directly.","multi":false},{"chapter":12,"num":4,"text":"An IAM user with full access to all EC2 actions in all regions assumes a role that has access to only the EC2 RunInstances operation in the us-east-1 region. What will the user be able to do under the assumed role?","options":{"A":"Create a new instance in any region.","B":"Create a new instance in the us-east-1 region.","C":"Start an existing instance in the us-east-1 region.","D":"Start an existing instance in any region."},"answer":["B"],"explanation":"When a user assumes a role, their effective permissions are the intersection of their user permissions and the role's permissions. The role only allows RunInstances (which creates new instances) in us-east-1, so that is all the user can do.","multi":false},{"chapter":12,"num":5,"text":"Several objects in a S3 bucket are encrypted using a KMS customer master key. Which of the following will give an IAM user permission to decrypt these objects?","options":{"A":"Add the user to the key policy as a key user.","B":"Grant the user access to the key using an IAM policy.","C":"Add the user to the key policy as a key administrator.","D":"Add the user as a principal to the bucket policy."},"answer":["A"],"explanation":"To decrypt objects encrypted with a KMS CMK, the user must be a key user in the KMS key policy. Key users can use the key for cryptographic operations like encrypt and decrypt. Key administrators can manage the key but not necessarily use it for decryption.","multi":false},{"chapter":12,"num":6,"text":"You run a public-facing application on EC2 instances. The application is backed by a database running on RDS. Users access it using multiple domain names that are hosted in Route 53. You want to get an idea of what IP addresses are accessing your application. Which of the following would you stream to CloudWatch Logs to get this information?","options":{"A":"RDS logs","B":"DNS query logs","C":"VPC flow logs","D":"CloudTrail logs"},"answer":["C"],"explanation":"VPC flow logs capture information about IP traffic going to and from network interfaces in your VPC, including source and destination IP addresses. This is the best source for identifying which IP addresses are accessing your application.","multi":false},{"chapter":12,"num":7,"text":"You're running a web server that keeps a detailed log of web requests. You want to determine which IP address has made the most requests in the last 24 hours. What should you do to accomplish this? (Choose two.)","options":{"A":"Create a metric filter.","B":"Stream the web server logs to CloudWatch Logs.","C":"Upload the web server log to S3.","D":"Use Athena to query the data."},"answer":["B, D"],"explanation":"By streaming web server logs to CloudWatch Logs, you can then use Athena to query the log data to identify the IP address with the most requests. Alternatively, uploading to S3 and using Athena also works, but streaming to CloudWatch is more real-time.","multi":false},{"chapter":12,"num":8,"text":"An application running on an EC2 instance has been updated to send large amounts of data to a server in your datacenter for backup. Previously, the instance generated very little traffic. Which GuardDuty finding type is this likely to trigger?","options":{"A":"Behavior","B":"Backdoor","C":"Stealth","D":"ResourceConsumption"},"answer":["A"],"explanation":"GuardDuty Behavior findings are triggered when an EC2 instance exhibits unusual behavior compared to its baseline, such as a sudden large increase in outbound data transfer to an external server.","multi":false},{"chapter":12,"num":9,"text":"You've set up an AWS Config managed rule to check whether a particular security group is attached to every instance in a VPC. You receive an SNS notification that an instance is out of compliance. But when you check the instance a few hours later, the security group is attached. Which of the following may help explain the apparent discrepancy? (Choose two.)","options":{"A":"The AWS Config timeline","B":"Lambda logs","C":"CloudTrail management event logs","D":"VPC flow logs"},"answer":["A, C"],"explanation":"The AWS Config timeline shows the history of configuration changes, explaining when the security group was removed and re-attached. CloudTrail management event logs record who made the API calls to modify the security group.","multi":false},{"chapter":12,"num":10,"text":"You want to use Amazon Inspector to analyze the security posture of your EC2 instances running Windows. Which rules package should you not use in your assessment?","options":{"A":"Common Vulnerabilities and Exposures","B":"Center for Internet Security Benchmarks","C":"Runtime Behavior Analysis","D":"Security Best Practices"},"answer":["D"],"explanation":"The Security Best Practices rules package in Amazon Inspector only supports Linux instances, not Windows. The other packages (CVE, CIS Benchmarks, Runtime Behavior Analysis) support both Linux and Windows.","multi":false},{"chapter":12,"num":11,"text":"You have a distributed application running in datacenters around the world. The application connects to a public Simple Queue Service (SQS) endpoint to send messages to a queue. How can you prevent an attacker from using this endpoint to gain unauthorized access to the queue? (Choose two.)","options":{"A":"Network access control lists","B":"Security groups","C":"IAM policies","D":"SQS access policies"},"answer":["C, D"],"explanation":"IAM policies control which IAM principals can access SQS, and SQS access policies (resource-based policies) control which AWS accounts, IAM users, roles, or services can send and receive messages. NACLs and security groups operate at the VPC/network level and don't protect public SQS endpoints.","multi":false},{"chapter":12,"num":12,"text":"You're using a public-facing application load balancer to forward traffic to EC2 instances in an Auto Scaling group. What can you do to ensure users on the Internet can reach the load balancer over HTTPS without reaching your instances directly? (Choose two.)","options":{"A":"Create a security group that allows all inbound traffic to TCP port 443.","B":"Attach the security group to the instances.","C":"Attach the security group to the load balancer.","D":"Remove the Internet gateway from the VPC.","E":"Create a security group that allows all inbound traffic to TCP port 80."},"answer":["B, C"],"explanation":"To ensure only the load balancer can reach the instances: create a security group allowing HTTPS (443) from anywhere and attach it to the load balancer (C), then create another security group on the instances that only allows traffic from the load balancer's security group (B).","multi":false},{"chapter":12,"num":13,"text":"You're running a UDP-based application on an EC2 instance. How can you protect it against a DDoS attack?","options":{"A":"Place the instance behind a network load balancer.","B":"Implement a security group to restrict inbound access to the instance.","C":"Place the instance behind an application load balancer.","D":"Enable AWS Shield Standard."},"answer":["A"],"explanation":"A Network Load Balancer (NLB) supports UDP traffic and provides protection against DDoS attacks by absorbing traffic spikes. Application Load Balancers don't support UDP. Shield Standard provides basic DDoS protection but placing the instance behind an NLB is more effective for UDP.","multi":false},{"chapter":12,"num":14,"text":"You're running a web application on six EC2 instances behind a network load balancer. The web application uses a MySQL database. How can you protect your application against SQL injection attacks? (Choose two.)","options":{"A":"Enable WAF.","B":"Assign elastic IP addresses to the instances.","C":"Place the instances behind an application load balancer.","D":"Block TCP port 3306."},"answer":["A, C"],"explanation":"AWS WAF can filter HTTP/HTTPS traffic and block SQL injection attempts using managed rules. Placing instances behind an Application Load Balancer enables WAF integration at Layer 7. Blocking port 3306 and assigning EIPs do not protect against SQL injection.","multi":false},{"chapter":12,"num":15,"text":"Which services protect against an HTTP flood attack?","options":{"A":"GuardDuty","B":"WAF","C":"Shield Standard","D":"Shield Advanced"},"answer":["B"],"explanation":"AWS WAF can protect against HTTP flood attacks by creating rate-based rules that limit the number of requests from a single IP address. Shield Standard and Advanced protect against network-layer DDoS attacks, and GuardDuty is for threat detection, not active protection.","multi":false},{"chapter":12,"num":16,"text":"Your security policy requires that you use a KMS key for encrypting S3 objects. It further requires this key be rotated once a year and revoked when misuse is detected. Which key type should you use? (Choose two.)","options":{"A":"Customer-managed CMK","B":"AWS-managed CMK","C":"S3-managed key","D":"Customer-provided key"},"answer":["A, B"],"explanation":"Both customer-managed CMKs and AWS-managed CMKs support annual key rotation and can be disabled/revoked. Customer-managed CMKs give full control over rotation schedule and revocation. AWS-managed CMKs are rotated automatically every year. S3-managed keys and customer-provided keys don't support the same level of control.","multi":false},{"chapter":12,"num":17,"text":"A developer is designing an application to run on AWS and has asked for your input in deciding whether to use a SQL database or DynamoDB for storing highly transactional application data. Your security policy requires all application data to be encrypted and encryption keys to be rotated every 90 days. Which AWS service should you recommend for storing application data? (Choose two.)","options":{"A":"KMS","B":"RedShift","C":"DynamoDB","D":"RDS"},"answer":["C, D"],"explanation":"Both DynamoDB and RDS support encryption at rest using KMS, and KMS allows key rotation on a schedule. They are both valid for storing highly transactional data with encryption requirements. KMS is the key management service, not a database. Redshift is optimized for analytics, not transactions.","multi":false},{"chapter":12,"num":18,"text":"You need to copy the data from an unencrypted EBS volume to another region and encrypt it. How can you accomplish this? (Choose two.)","options":{"A":"Create an encrypted snapshot of the unencrypted volume.","B":"Simultaneously encrypt and copy the snapshot to the destination region.","C":"Copy the encrypted snapshot to the destination region.","D":"Create an unencrypted snapshot of the unencrypted volume."},"answer":["A, C"],"explanation":"You can create an encrypted snapshot from an unencrypted EBS volume by specifying encryption during the snapshot copy process. Then copy that encrypted snapshot to the destination region. Alternatively: create an unencrypted snapshot (D), copy it to the destination region with encryption enabled \u2014 but A and C is the more direct two-step process.","multi":false},{"chapter":12,"num":19,"text":"An instance with an unencrypted EBS volume has an unencrypted EFS filesystem mounted on it. You need to encrypt the data on an existing EFS filesystem using a KMS key. How can you accomplish this?","options":{"A":"Encrypt the EBS volume of the instance.","B":"Create a new encrypted EFS filesystem and copy the data to it.","C":"Enable encryption on the existing EFS filesystem.","D":"Use a third-party encryption program to encrypt the data."},"answer":["B"],"explanation":"EFS encryption cannot be enabled on an existing filesystem \u2014 it must be enabled at creation time. The only way to encrypt an existing unencrypted EFS filesystem is to create a new encrypted EFS filesystem and migrate the data to it.","multi":false},{"chapter":12,"num":20,"text":"On which of the following can you not use an ACM-generated TLS certificate? (Choose two.)","options":{"A":"An S3 bucket","B":"A CloudFront distribution","C":"An application load balancer","D":"An EC2 instance"},"answer":["A, D"],"explanation":"ACM certificates cannot be directly used with S3 buckets (S3 static hosting uses its own certificate) or EC2 instances (ACM doesn't export private keys for use on EC2). ACM certificates can be deployed on CloudFront distributions and application load balancers.","multi":false},{"chapter":12,"num":21,"text":"Which of the following assesses the security posture of your AWS resources against AWS best practices?","options":{"A":"Detective","B":"Macie","C":"Security Hub","D":"GuardDuty"},"answer":["C"],"explanation":"AWS Security Hub aggregates security findings from multiple AWS services and assesses your environment against AWS security best practices and industry standards. GuardDuty detects threats, Macie identifies sensitive data in S3, and Detective helps investigate security incidents.","multi":false},{"chapter":13,"num":1,"text":"Which of the following best describes the AWS Free Tier?","options":{"A":"Free access to AWS services for a new account's first month","B":"Free access to all instance types of AWS EC2 instances for new accounts","C":"Free access to basic levels of AWS services for a new account's first year","D":"Unlimited and open-ended access to the 'free tier' of most AWS services"},"answer":["C"],"explanation":"The AWS Free Tier provides free access to a limited set of AWS services (up to certain usage limits) for the first 12 months of a new AWS account. Some services are always free or have always-free tiers beyond the 12-month period.","multi":false},{"chapter":13,"num":2,"text":"Which of the following storage classes provides the least expensive storage and transfer rates?","options":{"A":"Amazon S3 Glacier","B":"Amazon S3 Standard-Infrequent Access","C":"Amazon S3 Standard","D":"Amazon S3 One Zone-Infrequent Access"},"answer":["A"],"explanation":"Amazon S3 Glacier offers the lowest storage cost among all S3 storage classes, designed for long-term archival where retrieval times of minutes to hours are acceptable. It has very low storage rates and retrieval fees but no transfer costs for ingest.","multi":false},{"chapter":13,"num":3,"text":"Which AWS service is best suited to controlling your spending by sending email alerts?","options":{"A":"Cost Explorer","B":"Budgets","C":"Organizations","D":"TCO Calculator"},"answer":["B"],"explanation":"AWS Budgets allows you to set custom cost and usage budgets and configure email (or SNS) alerts when your actual or forecasted spending exceeds defined thresholds.","multi":false},{"chapter":13,"num":4,"text":"Your AWS infrastructure is growing and you're beginning to have trouble keeping track of what you're spending. Which AWS service is best suited to analyzing account usage data at scale?","options":{"A":"Trusted Advisor","B":"Cost Explorer","C":"Budgets","D":"Cost and Usage Reports"},"answer":["D"],"explanation":"AWS Cost and Usage Reports provide the most detailed data about your AWS spending, including hourly and resource-level granularity. It is best suited for large-scale analysis by exporting to S3 and querying with Athena or Redshift.","multi":false},{"chapter":13,"num":5,"text":"Your company wants to more closely coordinate the administration of its multiple AWS accounts, and AWS Organizations can help it do that. How does that change your security profile? (Choose three.)","options":{"A":"An organization-level administration account breach is potentially more damaging.","B":"User permissions can be controlled centrally at the organization level.","C":"You should upgrade to use only specially hardened organization-level VPCs.","D":"Standard security best practices such as MFA and strong passwords are even more essential.","E":"You should upgrade all of your existing security groups to account for the changes."},"answer":["A, B, D"],"explanation":"Using AWS Organizations increases the impact of a root account breach (A), enables centralized permission control via SCPs (B), and makes strong security practices like MFA even more critical (D). Organization-level VPCs and updating security groups are not required changes.","multi":false},{"chapter":13,"num":6,"text":"Which of the following resource states are monitored by AWS Trusted Advisor? (Choose two.)","options":{"A":"Route 53 routing failures","B":"Running but idle EC2 instances","C":"S3 buckets with public read access permissions","D":"EC2 Linux instances that allow root account SSH access","E":"Unencrypted S3 bucket data transfers"},"answer":["B, C"],"explanation":"AWS Trusted Advisor monitors for running but idle EC2 instances (cost optimization) and S3 buckets with public read access (security). These are standard Trusted Advisor checks. Route 53 routing failures and SSH root access are not standard Trusted Advisor checks.","multi":false},{"chapter":13,"num":7,"text":"You're planning a new AWS deployment, and your team is debating whether they'll be better off using an RDS database or one run on an EC2 instance. Which of the following tools will be most helpful?","options":{"A":"TCO Calculator","B":"AWS Pricing Calculator","C":"Trusted Advisor","D":"Cost and Usage Reports"},"answer":["B"],"explanation":"The AWS Pricing Calculator allows you to estimate and compare the costs of different AWS service configurations, making it ideal for comparing the cost of RDS versus a self-managed database on EC2 before making a deployment decision.","multi":false},{"chapter":13,"num":8,"text":"Which of the following is not a metric you can configure an AWS budget to track?","options":{"A":"EBS volume capacity","B":"Resource usage","C":"Reserve instance coverage","D":"Resource cost"},"answer":["A"],"explanation":"AWS Budgets can track cost, usage, Reserved Instance coverage, and Savings Plans coverage/utilization. EBS volume capacity is not a metric that AWS Budgets can track \u2014 it is an infrastructure metric monitored by CloudWatch.","multi":false},{"chapter":13,"num":9,"text":"Which of the following statements are true of cost allocation tags? (Choose two.)","options":{"A":"Tags can take up to 24 hours before they appear in the Billing and Cost Management dashboard.","B":"Tags can't be applied to resources that were launched before the tags were created.","C":"You're allowed five free budgets per account.","D":"You can activate and manage cost allocation tags from the Tag Editor page."},"answer":["A, B"],"explanation":"Cost allocation tags can take up to 24 hours to appear in the billing dashboard after activation (A). Tags cannot be retroactively applied to past resource usage \u2014 they only apply to costs incurred after the tag is applied (B).","multi":false},{"chapter":13,"num":10,"text":"Your online web store normally requires three EC2 instances to handle traffic but experiences a twofold increase in traffic for the two summer months. Which of the following approaches makes the most sense?","options":{"A":"Run three on-demand instances 12 months per year and schedule six reserve instances for the summer months.","B":"Run spot instances for the summer months and three reserve instances 12 months/year.","C":"Run nine reserve instances for 12 months/year.","D":"Run three reserve instances 12 months/year and purchase three scheduled reserve instances for the summer months."},"answer":["D"],"explanation":"Running three reserved instances year-round covers baseline traffic at the lowest cost. Purchasing three scheduled reserved instances for the two summer months (to handle the 2x spike) is more cost-effective than running on-demand or spot instances for the peak.","multi":false},{"chapter":13,"num":11,"text":"Which of the following settings do you not need to provide when configuring a reserved instance?","options":{"A":"Payment option","B":"Standard or Convertible RI","C":"Interruption policy","D":"Tenancy"},"answer":["C"],"explanation":"When configuring a Reserved Instance, you specify the payment option (all/partial/no upfront), RI type (Standard or Convertible), and tenancy (shared or dedicated). Interruption policy is a setting for Spot Instances, not Reserved Instances.","multi":false},{"chapter":13,"num":12,"text":"Your new web application requires multiple EC2 instances running 24/7 and you're going to purchase reserved instances. Which of the following payment options is the most expensive when configuring a reserve instance?","options":{"A":"All Upfront","B":"Partial Upfront","C":"No Upfront","D":"Monthly"},"answer":["C"],"explanation":"No Upfront reserved instances have the highest total cost over the term because you pay monthly without any upfront discount. All Upfront is the cheapest option overall. 'Monthly' is not a standard RI payment option.","multi":false},{"chapter":13,"num":13,"text":"Which of the following benefits of containers such as Docker can significantly reduce your AWS compute costs? (Choose two.)","options":{"A":"Containers can launch quickly.","B":"Containers can deliver increased server density.","C":"Containers make it easy to reliably replicate server environments.","D":"Containers can run using less memory than physical machines."},"answer":["A, B"],"explanation":"Containers launch in seconds (vs minutes for VMs), allowing faster Auto Scaling responses to demand changes and reducing idle capacity costs (A). Higher server density means more workloads per EC2 instance, directly reducing compute costs (B).","multi":false},{"chapter":13,"num":14,"text":"Which of the following is the best use of an EC2 reserved instance?","options":{"A":"An application that will run continuously for six months straight","B":"An application that will run continuously for 36 months straight","C":"An application that runs only during local business hours","D":"An application that runs at unpredictable times and can survive unexpected shutdowns"},"answer":["B"],"explanation":"Reserved instances offer the best savings (up to 72%) for workloads that run continuously for 1 or 3 years. A 36-month (3-year) continuously running application is the ideal use case for a Reserved Instance. Six months doesn't benefit from RI pricing, and intermittent workloads are better suited for On-Demand or Spot.","multi":false},{"chapter":13,"num":15,"text":"Which of the following describes 'unused EC2 instances matching a particular set of launch specifications'?","options":{"A":"Request type","B":"Spot instance interruption","C":"Spot fleet","D":"Spot instance pool"},"answer":["D"],"explanation":"A Spot Instance pool is a set of unused EC2 instances with the same instance type, operating system, availability zone, and network platform. When you request Spot Instances, AWS draws from these pools.","multi":false},{"chapter":13,"num":16,"text":"Which of the following best describes a spot instance interruption?","options":{"A":"A spot instance interruption occurs when the spot price rises above your maximum.","B":"A spot instance interruption is the termination of a spot instance when its workload completes.","C":"A spot instance interruption occurs when a spot request is manually restarted.","D":"A spot instance interruption is the result of a temporary outage in an AWS datacenter."},"answer":["A"],"explanation":"A Spot Instance interruption occurs when EC2 needs to reclaim the instance capacity \u2014 most commonly when the Spot price rises above the maximum price you specified. AWS provides a 2-minute warning before termination.","multi":false},{"chapter":13,"num":17,"text":"Which of the following describes the maximum instances or vCPUs you want running?","options":{"A":"Spot instance pool","B":"Target capacity","C":"Spot maximum","D":"Spot cap"},"answer":["B"],"explanation":"Target capacity defines the total number of instances or vCPUs you want running in a Spot Fleet. AWS will attempt to maintain this capacity by launching and replacing Spot Instances as needed.","multi":false},{"chapter":13,"num":18,"text":"You need to make sure your EBS volumes are regularly backed up, but you're afraid you'll forget to remove older snapshot versions, leading to expensive data bloat. What's the best solution to this problem?","options":{"A":"Configure the EBS Lifecycle Manager.","B":"Create a script that will regularly invoke the AWS CLI to prune older snapshots.","C":"Configure an EBS Scheduled Reserved Instance.","D":"Tie a string to your finger.","E":"Configure an S3 Lifecycle configuration policy to remove old snapshots."},"answer":["A"],"explanation":"Amazon Data Lifecycle Manager (DLM) for EBS snapshots automates the creation, retention, and deletion of EBS snapshots based on policies you define, solving both the backup scheduling and snapshot cleanup problems without any custom scripting.","multi":false},{"chapter":13,"num":19,"text":"Which of these AWS CLI commands will launch a spot fleet?","options":{"A":"aws ec2 request-fleet --spot-fleet-request-config file://Config.json","B":"aws ec2 spot-fleet --spot-fleet-request-config file://Config.json","C":"aws ec2 launch-spot-fleet --spot-fleet-request-config/ file://Config.json","D":"aws ec2 request-spot-fleet --spot-fleet-request-config file://Config.json"},"answer":["D"],"explanation":"The correct AWS CLI command to request a Spot Fleet is 'aws ec2 request-spot-fleet --spot-fleet-request-config file://Config.json'. The command is 'request-spot-fleet' and the parameter is '--spot-fleet-request-config'.","multi":false},{"chapter":13,"num":20,"text":"Which of the following elements is not something you'd include in your spot fleet request?","options":{"A":"Availability zone","B":"Target capacity","C":"Platform (the instance OS)","D":"AMI"},"answer":["A"],"explanation":"A Spot Fleet request includes target capacity, the AMI, and platform (instance OS) among its launch specifications. Availability zone is optional \u2014 by default, the fleet can launch in any AZ to find the best pricing. It is not a required element.","multi":false}];
export const CHAPTER_TITLES = {"1":"Getting Started with Cloud and AWS","2":"Amazon EC2 and EBS","3":"AWS Storage Services","4":"AWS Networking","5":"Route 53 and DNS","6":"Databases on AWS","7":"Serverless and Application Services","8":"Containers and EKS","9":"Security, Identity and Compliance","10":"Monitoring, Logging and Audit","11":"High Availability and Disaster Recovery","12":"Cost Optimization","13":"Migration and Advanced Architectures"};
export const TOTAL_BOOK = 280;
